import { useEffect } from 'react';
import { useBrand } from '../app/context.js';

/**
 * The browser tab's title, `Search · Cloud Digital Library` (the brand alone without a title).
 * The site is a single-page app, so titles are set in the browser for history, bookmarks and
 * the crawlers that run JavaScript.
 */
export function useDocumentTitle(title: string | undefined): void {
  const { name } = useBrand();
  useEffect(() => {
    document.title = title === undefined || title === '' ? name : `${title} · ${name}`;
  }, [title, name]);
}

/**
 * `<meta name="robots" content="noindex">` while the calling page is shown: a client-side "not
 * found" answers HTTP 200, so this keeps it out of search indexes.
 */
export function useNoIndex(): void {
  useEffect(() => {
    const meta = document.createElement('meta');
    meta.name = 'robots';
    meta.content = 'noindex';
    document.head.append(meta);
    return () => {
      meta.remove();
    };
  }, []);
}

/** Sets `<meta name="description">` (once at startup, from `site.json`). */
export function setMetaDescription(text: string): void {
  let meta = document.head.querySelector<HTMLMetaElement>('meta[name="description"]');
  if (meta === null) {
    meta = document.createElement('meta');
    meta.name = 'description';
    document.head.append(meta);
  }
  meta.content = text;
}
