import { z } from 'zod';

/**
 * Runtime configuration: `/config.json`, served next to `index.html` by whatever hosts the site,
 * so one build serves every deployment. The site meets the backend only at these URLs; the
 * Public API and the IIIF image service allow any origin (CORS `*`).
 *
 * ```json
 * { "apiBaseUrl": "https://<STAFF_UI_DOMAIN>/api/v1" }
 * ```
 */
export interface SiteConfig {
  /** The Public API, e.g. `https://library.example.org/api/v1` (no trailing slash). */
  readonly apiBaseUrl: string;
  /** The IIIF Image API 3.0 base; defaults to `/iiif/3` on the API's origin. */
  readonly iiifImageBaseUrl: string;
}

const HttpUrl = z
  .url({ protocol: /^https?$/ })
  .transform((url) => url.replace(/\/+$/, ''))
  .refine((url) => !/[?#]/.test(url), { message: 'must not have a query or fragment' });

export const ConfigFile = z.object({
  apiBaseUrl: HttpUrl,
  iiifImageBaseUrl: HttpUrl.optional(),
});

export function parseConfig(value: unknown): SiteConfig {
  const parsed = ConfigFile.safeParse(value);
  if (!parsed.success) throw new Error(`config.json is invalid: ${z.prettifyError(parsed.error)}`);
  const { apiBaseUrl, iiifImageBaseUrl } = parsed.data;
  return {
    apiBaseUrl,
    iiifImageBaseUrl: iiifImageBaseUrl ?? `${new URL(apiBaseUrl).origin}/iiif/3`,
  };
}

/** `/config.json`; the site cannot start without it, so failures throw (the startup page says why). */
export async function loadConfig(fetchImpl: typeof fetch = fetch): Promise<SiteConfig> {
  const response = await fetchImpl(new URL('config.json', document.baseURI).href, { cache: 'no-store' });
  if (!response.ok || !(response.headers.get('content-type') ?? '').includes('json')) {
    throw new Error(
      `config.json is missing (HTTP ${String(response.status)}). It names the Public API: { "apiBaseUrl": "https://…/api/v1" }.`,
    );
  }
  return parseConfig(await response.json());
}
