import { useNavigate } from 'react-router';
import { useSite } from '../app/context.js';
import { useDocumentTitle, useNoIndex } from '../lib/document.js';
import { IiifImage } from './IiifImage.js';
import { Container } from './layout.js';
import { SearchBox } from './SearchBox.js';
import { TextLink } from './links.js';

/**
 * "We're not in Kansas anymore": no page at this address, or the work or collection it named is
 * not public. The single-page app answers HTTP 200 for every path, so the page is marked
 * `noindex`. Routes render it for unknown paths; pages render it for an API 404.
 */
export function NotFound() {
  useDocumentTitle('Page not found');
  useNoIndex();
  const navigate = useNavigate();
  const site = useSite();
  const image = site.notFound;
  return (
    <Container className="grid items-center gap-12 py-12 md:py-16 lg:grid-cols-[1fr_380px]">
      <div>
        <p className="font-mono text-sm text-muted-foreground">404</p>
        <h1 className="mt-2 font-heading text-4xl leading-tight font-semibold tracking-tight md:text-[44px]">
          We’re not in Kansas anymore
        </h1>
        <p className="mt-3 max-w-lg text-lg text-muted-foreground">
          There is no page at this address. The item may have been unpublished, or the link
          mistyped.
        </p>
        <SearchBox
          size="lg"
          button
          landmark="Search instead"
          className="mt-7 max-w-lg"
          onSearch={(q) => {
            void navigate(q === '' ? '/search' : `/search?q=${encodeURIComponent(q)}`);
          }}
        />
        <nav
          aria-label="Ways back"
          className="mt-5 flex flex-wrap gap-x-5 gap-y-2 text-sm font-medium"
        >
          <TextLink to="/">Home</TextLink>
          <TextLink to="/collections">All collections</TextLink>
          <TextLink to="/about#contact">Contact us</TextLink>
        </nav>
      </div>
      {image !== undefined && (
        <figure className="hidden lg:block">
          <IiifImage
            fileSetId={image.fileSetId}
            size={800}
            className="w-full rounded-xl object-contain ring-1 ring-border"
          />
          {image.caption !== undefined && (
            <figcaption className="mt-2 text-xs text-muted-foreground">{image.caption}</figcaption>
          )}
        </figure>
      )}
    </Container>
  );
}
