import { ClockIcon, CodeIcon, MailIcon, MapPinIcon, PhoneIcon } from 'lucide-react';
import type { ReactNode } from 'react';
import { useIiif } from '../api/iiif.js';
import { useCollections } from '../api/queries.js';
import { useBrand, useConfig, useSite } from '../app/context.js';
import { IiifImage } from '../components/IiifImage.js';
import { Container } from '../components/layout.js';
import { TEXT_LINK } from '../components/links.js';
import { useDocumentTitle } from '../lib/document.js';

function DeveloperLink({
  href,
  icon,
  title,
  detail,
}: {
  readonly href: string;
  readonly icon: ReactNode;
  readonly title: string;
  readonly detail: string;
}) {
  return (
    <a
      href={href}
      rel="noreferrer"
      className="flex min-w-0 items-center gap-3 rounded-lg border border-border bg-card p-3 hover:bg-secondary/50 focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
    >
      <span className="grid size-9 shrink-0 place-items-center rounded-md bg-secondary">
        {icon}
      </span>
      <span className="min-w-0">
        <span className="block text-sm font-medium">{title}</span>
        <span className="block truncate font-mono text-[11px] text-muted-foreground">{detail}</span>
      </span>
    </a>
  );
}

function ContactItem({
  icon: Icon,
  children,
}: {
  readonly icon: typeof MailIcon;
  readonly children: ReactNode;
}) {
  return (
    <li className="flex gap-2.5">
      <Icon aria-hidden="true" className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
      <span className="min-w-0">{children}</span>
    </li>
  );
}

/**
 * About and contact, from `site.json`: the lead paragraphs and further sections, "For
 * developers" (the Public API and IIIF addresses this deployment's `config.json` names), and a
 * contact card with a mail link (no form: a form would need a backend).
 */
export function AboutPage() {
  const brand = useBrand();
  const config = useConfig();
  const { about, contact, description } = useSite();
  const title = about?.title ?? `About ${brand.name}`;
  useDocumentTitle(title);
  const [lead, ...rest] = about?.body ?? [description];
  const api = new URL(config.apiBaseUrl);
  const iiif = useIiif();
  // A real IIIF collection to open; the collections list until it is known.
  const firstCollection = useCollections().data?.[0];
  const hasContact =
    contact !== undefined &&
    (contact.email !== undefined ||
      contact.phone !== undefined ||
      (contact.address?.length ?? 0) > 0 ||
      contact.hours !== undefined);

  return (
    <Container className="grid gap-12 py-10 md:py-12 lg:grid-cols-[minmax(0,1fr)_360px]">
      <article className="max-w-2xl">
        <h1 className="font-heading text-3xl leading-tight font-semibold tracking-tight md:text-[34px]">
          {title}
        </h1>
        {lead !== undefined && (
          <p className="mt-4 font-heading text-xl leading-relaxed text-foreground/90">{lead}</p>
        )}
        {rest.map((paragraph) => (
          <p key={paragraph} className="mt-4 leading-relaxed text-muted-foreground">
            {paragraph}
          </p>
        ))}
        {about?.sections?.map((section) => (
          <section key={section.heading} className="mt-10">
            <h2 className="font-heading text-[22px] font-semibold">{section.heading}</h2>
            {section.body.map((paragraph) => (
              <p key={paragraph} className="mt-2 leading-relaxed text-muted-foreground">
                {paragraph}
              </p>
            ))}
          </section>
        ))}
        <section id="developers" aria-labelledby="developers-title" className="mt-10 scroll-mt-6">
          <h2 id="developers-title" className="font-heading text-[22px] font-semibold">
            For developers
          </h2>
          <p className="mt-2 leading-relaxed text-muted-foreground">
            Every item has a IIIF Presentation 3 manifest and every image a IIIF Image API service;
            the anonymous Public API answers search with facets. All of it is open data, usable from
            any website.
          </p>
          <div className="mt-4 grid gap-3 sm:grid-cols-2">
            <DeveloperLink
              href={
                firstCollection !== undefined
                  ? iiif.collection(firstCollection.id)
                  : `${config.apiBaseUrl}/collections`
              }
              icon={
                <span aria-hidden="true" className="font-mono text-[11px] font-bold">
                  IIIF
                </span>
              }
              title="IIIF collections"
              detail={`${api.pathname.replace(/\/$/, '')}/iiif/collections/{id}`}
            />
            <DeveloperLink
              href={`${config.apiBaseUrl}/search`}
              icon={<CodeIcon aria-hidden="true" className="size-4" />}
              title="Public API"
              detail={`${api.host}${api.pathname.replace(/\/$/, '')}`}
            />
          </div>
        </section>
      </article>
      <aside className="grid content-start gap-4">
        {hasContact && (
          <section
            id="contact"
            aria-labelledby="contact-title"
            className="scroll-mt-6 rounded-xl border border-border bg-card p-5"
          >
            <h2
              id="contact-title"
              className="text-xs font-semibold tracking-wider text-muted-foreground uppercase"
            >
              Contact us
            </h2>
            {contact.name !== undefined && (
              <p className="mt-2 font-heading text-lg font-semibold">{contact.name}</p>
            )}
            <ul className="mt-3 grid gap-2.5 text-sm">
              {contact.email !== undefined && (
                <ContactItem icon={MailIcon}>
                  <a className={TEXT_LINK} href={`mailto:${contact.email}`}>
                    {contact.email}
                  </a>
                </ContactItem>
              )}
              {contact.phone !== undefined && (
                <ContactItem icon={PhoneIcon}>
                  <a className={TEXT_LINK} href={`tel:${contact.phone.replace(/[^\d+]/g, '')}`}>
                    {contact.phone}
                  </a>
                </ContactItem>
              )}
              {contact.address !== undefined && contact.address.length > 0 && (
                <ContactItem icon={MapPinIcon}>
                  <address className="not-italic">
                    {contact.address.map((line) => (
                      <span key={line} className="block">
                        {line}
                      </span>
                    ))}
                  </address>
                </ContactItem>
              )}
              {contact.hours !== undefined && (
                <ContactItem icon={ClockIcon}>{contact.hours}</ContactItem>
              )}
            </ul>
          </section>
        )}
        {about?.fileSetId !== undefined && (
          <IiifImage
            fileSetId={about.fileSetId}
            size={800}
            className="w-full rounded-xl object-cover ring-1 ring-border"
          />
        )}
      </aside>
    </Container>
  );
}
