import { useBrand } from '../app/context.js';
import { cn } from '@/lib/utils';

/** The institution's logo from `/theme.json`, or its short name on the primary colour. */
export function BrandMark({ className }: { readonly className?: string }) {
  const brand = useBrand();
  if (brand.logo !== undefined) {
    return (
      <img
        src={brand.logo}
        alt=""
        className={cn('size-9 shrink-0 rounded-lg object-contain', className)}
      />
    );
  }
  return (
    <span
      aria-hidden="true"
      className={cn(
        'grid size-9 shrink-0 place-items-center rounded-lg bg-primary font-heading text-[13px] font-bold text-primary-foreground',
        className,
      )}
    >
      {brand.shortName}
    </span>
  );
}
