import { CodeIcon } from 'lucide-react';
import { Link } from 'react-router';
import type { FacetValue, SearchResults } from '../../api/client.js';
import { useSearch } from '../../api/queries.js';
import { useBrand, useSite } from '../../app/context.js';
import { IiifImage } from '../../components/IiifImage.js';
import { SectionHeading } from '../../components/layout.js';
import { ButtonLink } from '../../components/links.js';
import { WorkCard } from '../../components/WorkCard.js';
import { searchHref } from '../../lib/browse-links.js';
import { decadeLabel } from '../../lib/dates.js';
import { worksLabel } from '../collections/CollectionCard.js';

/** How many decades the chart shows: as many as fit beside the subjects, fewer on a phone. */
const CHART_DECADES = 8;
const PHONE_DECADES = 6;

/**
 * The decades a chart shows, in order: all of them when they fit, else those with the most works
 * (ties to the earlier), each with its rank so a phone can drop the least of them.
 */
export function chartDecades(
  decades: readonly FacetValue[],
): readonly { readonly decade: FacetValue; readonly rank: number }[] {
  const ranked = decades
    .map((decade, index) => ({ decade, index }))
    .sort((a, b) => b.decade.count - a.decade.count || a.index - b.index)
    .slice(0, CHART_DECADES)
    .map((entry, rank) => ({ ...entry, rank }));
  return ranked.sort((a, b) => a.index - b.index).map(({ decade, rank }) => ({ decade, rank }));
}

/**
 * "Browse by decade": the year facet of an empty search as bars, each a filtered search. A
 * collection spanning centuries has hundreds of decades (the Met's reach back to 3650 BCE), so
 * the chart keeps the busiest few and links to the rest on the search page.
 */
export function DecadeChart({ decades }: { readonly decades: readonly FacetValue[] }) {
  const shown = chartDecades(decades);
  const max = Math.max(1, ...shown.map(({ decade }) => decade.count));
  return (
    <section aria-labelledby="decades-title" className="min-w-0">
      <SectionHeading
        id="decades-title"
        {...(decades.length > shown.length
          ? {
              link: {
                text: `All ${decades.length.toLocaleString('en-US')} decades`,
                to: '/search',
              },
            }
          : {})}
      >
        Browse by decade
      </SectionHeading>
      <ul className="mt-5 flex items-end gap-2 sm:gap-3">
        {shown.map(({ decade, rank }) => (
          <li
            key={decade.value}
            className={`min-w-0 flex-1${rank >= PHONE_DECADES ? ' max-sm:hidden' : ''}`}
          >
            <Link
              to={searchHref({ year: decade.value })}
              className="group grid justify-items-center gap-2 rounded-md text-center focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
            >
              <span
                aria-hidden="true"
                className="w-full rounded-t-md bg-primary/80 transition-colors group-hover:bg-primary motion-reduce:transition-none"
                style={{ height: `${String(18 + Math.round((decade.count / max) * 96))}px` }}
              />
              <span className="font-heading text-base font-semibold sm:text-lg">
                {decadeLabel(decade.value)}
              </span>{' '}
              <span className="-mt-1.5 text-xs text-muted-foreground">
                {worksLabel(decade.count)}
              </span>
            </Link>
          </li>
        ))}
      </ul>
    </section>
  );
}

/** "Popular subjects": the top subjects, then the top genres, as filtered-search chips. */
export function PopularSubjects({ facets }: { readonly facets: SearchResults['facets'] }) {
  const chips = [
    ...facets.subject.slice(0, 6).map((value) => ({ value, facet: 'subject' as const })),
    ...facets.genre.slice(0, 3).map((value) => ({ value, facet: 'genre' as const })),
  ];
  return (
    <section aria-labelledby="subjects-title">
      <SectionHeading id="subjects-title">Popular subjects</SectionHeading>
      <ul className="mt-5 flex flex-wrap gap-2">
        {chips.map(({ value, facet }) => (
          <li key={`${facet} ${value.value}`}>
            <Link
              to={searchHref({ [facet]: [value.value] })}
              className="inline-flex items-center gap-1.5 rounded-full border border-border bg-card px-3 py-1 text-[13px] text-foreground hover:border-primary/40 hover:bg-primary/5 focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
            >
              {value.label}{' '}
              <span className="text-muted-foreground tabular-nums">{value.count}</span>
            </Link>
          </li>
        ))}
      </ul>
    </section>
  );
}

/**
 * "Recently added": the newest works, with the API's `recent` sort (optional B1). It is asked
 * for only on an API with B1 (`enabled`: an older one refuses the sort with a 400, which the
 * browser logs); an answer in another order leaves the row out too.
 */
export function RecentlyAdded({ enabled }: { readonly enabled: boolean }) {
  const recent = useSearch({ sort: 'recent', limit: 6, facetLimit: 1 }, { enabled });
  const data = recent.data;
  if (data?.sort !== 'recent' || data.items.length === 0) return null;
  return (
    <section aria-labelledby="recent-title" className="grid gap-6">
      <SectionHeading id="recent-title" link={{ text: 'See all', to: '/search?sort=recent' }}>
        Recently added
      </SectionHeading>
      <ul className="grid grid-cols-2 gap-x-5 gap-y-7 sm:grid-cols-3 lg:grid-cols-6">
        {data.items.map((work) => (
          <li key={work.id}>
            <WorkCard work={work} aspect="aspect-[3/4]" />
          </li>
        ))}
      </ul>
    </section>
  );
}

/** The about card: `site.json`'s about title and first paragraph, its image, two ways on. */
export function AboutCard() {
  const brand = useBrand();
  const { about, description } = useSite();
  const fileSetId = about?.fileSetId;
  return (
    <section
      aria-labelledby="about-card-title"
      className="grid items-center gap-8 rounded-2xl border border-border bg-card p-6 md:p-8 lg:grid-cols-[1fr_1.2fr] lg:gap-10"
    >
      {fileSetId !== undefined && (
        <IiifImage
          fileSetId={fileSetId}
          size={1000}
          className="h-56 w-full rounded-xl object-cover object-top"
        />
      )}
      <div className={fileSetId === undefined ? 'lg:col-span-2' : undefined}>
        <p className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">
          About the library
        </p>
        <h2
          id="about-card-title"
          className="mt-2 font-heading text-[26px] leading-tight font-semibold"
        >
          {about?.title ?? `About ${brand.name}`}
        </h2>
        <p className="mt-3 text-muted-foreground">{about?.body[0] ?? description}</p>
        <div className="mt-5 flex flex-wrap gap-2">
          <ButtonLink to="/about" variant="default">
            Read more
          </ButtonLink>
          <ButtonLink to="/about#developers">
            <CodeIcon aria-hidden="true" />
            For developers
          </ButtonLink>
        </div>
      </div>
    </section>
  );
}
