import { Share2Icon } from 'lucide-react';
import { Link, useLocation } from 'react-router';
import { toast } from 'sonner';
import type { PublicCollection, SearchResults } from '../../api/client.js';
import { useIiif } from '../../api/iiif.js';
import { useSearch } from '../../api/queries.js';
import { IiifImage } from '../../components/IiifImage.js';
import { Container } from '../../components/layout.js';
import { ButtonLink } from '../../components/links.js';
import { searchHref } from '../../lib/browse-links.js';
import { decadeLabel } from '../../lib/dates.js';
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb';
import { Button, buttonVariants } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import { worksLabel } from './CollectionCard.js';

/**
 * A collection's dates: the exact years when every work is in hand, else the decades its works
 * fall in (`1930s–1940s`), or undefined when none is dated.
 */
export function collectionYears(results: SearchResults): string | undefined {
  if (results.items.length > 0 && results.items.length >= results.total) {
    const starts = results.items.map((hit) => hit.yearStart ?? hit.yearEnd);
    const ends = results.items.map((hit) => hit.yearEnd ?? hit.yearStart);
    const from = Math.min(...starts.filter((year) => year !== null));
    const to = Math.max(...ends.filter((year) => year !== null));
    if (Number.isFinite(from) && Number.isFinite(to)) {
      return from === to ? String(from) : `${String(from)}–${String(to)}`;
    }
  }
  const decades = results.facets.year.map((value) => value.value).sort();
  const first = decades[0];
  const last = decades.at(-1);
  if (first === undefined || last === undefined) return undefined;
  return first === last ? decadeLabel(first) : `${decadeLabel(first)}–${decadeLabel(last)}`;
}

/** The page's address (with its filters), to the system share sheet or the clipboard. */
async function shareLink(title: string, url: string): Promise<void> {
  if (typeof navigator.share === 'function') {
    try {
      await navigator.share({ title, url });
    } catch {
      // Dismissed: nothing to do.
    }
    return;
  }
  try {
    await navigator.clipboard.writeText(url);
    toast.success('Link copied');
  } catch {
    toast.error('Could not copy the link');
  }
}

const COLLAGE = 3;

/**
 * A collection's header: breadcrumbs, the title, description, its counts, dates and leading
 * genres, "Browse all", the IIIF collection and Share, and a collage of its images (the API's
 * thumbnails with B1, else its first works').
 */
export function CollectionHeader({ collection }: { readonly collection: PublicCollection }) {
  const iiif = useIiif();
  const location = useLocation();
  // The collection's first works with its facets; the dates when they are all of them.
  const overview = useSearch({
    filters: { collection: [collection.id] },
    limit: 12,
    facetLimit: 3,
  });
  const data = overview.data;
  const images =
    collection.thumbnailFileSetIds !== undefined && collection.thumbnailFileSetIds.length > 0
      ? collection.thumbnailFileSetIds.slice(0, COLLAGE)
      : (data?.items
          .map((hit) => hit.representativeFileSetId)
          .filter((id) => id !== null)
          .slice(0, COLLAGE) ?? []);
  const years = data !== undefined ? collectionYears(data) : undefined;
  const genres = data?.facets.genre.slice(0, 2).map((value) => value.label) ?? [];

  return (
    <section className="border-b border-border bg-card">
      <Container className="grid items-center gap-10 py-10 md:py-12 lg:grid-cols-[minmax(0,1fr)_480px] lg:gap-12">
        <div>
          <Breadcrumb className="mb-4">
            <BreadcrumbList className="text-[13px]">
              <BreadcrumbItem>
                <BreadcrumbLink render={<Link to="/collections" />}>Collections</BreadcrumbLink>
              </BreadcrumbItem>
              <BreadcrumbSeparator />
              <BreadcrumbItem>
                <BreadcrumbPage>{collection.title}</BreadcrumbPage>
              </BreadcrumbItem>
            </BreadcrumbList>
          </Breadcrumb>
          <p className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">
            Collection
          </p>
          <h1 className="mt-2 font-heading text-[32px] leading-[1.1] font-semibold tracking-tight md:text-[40px]">
            {collection.title}
          </h1>
          {collection.description !== null && (
            <p className="mt-4 max-w-xl text-base leading-relaxed text-muted-foreground">
              {collection.description}
            </p>
          )}
          <dl className="mt-5 flex flex-wrap items-baseline gap-x-6 gap-y-2 text-sm">
            <div className="flex items-baseline gap-1.5">
              <dt className="sr-only">Works</dt>
              <dd>
                <b className="font-heading text-lg">
                  {collection.workCount.toLocaleString('en-US')}
                </b>{' '}
                {collection.workCount === 1 ? 'work' : 'works'}
              </dd>
            </div>
            {years !== undefined && (
              <div>
                <dt className="sr-only">Dates</dt>
                <dd className="font-heading text-lg font-bold">{years}</dd>
              </div>
            )}
            {genres.length > 0 && (
              <div>
                <dt className="sr-only">Genres</dt>
                <dd>{genres.join(' · ')}</dd>
              </div>
            )}
          </dl>
          <div className="mt-6 flex flex-wrap gap-2">
            {collection.workCount > 0 && (
              <ButtonLink to={searchHref({ collection: [collection.id] })} variant="default">
                Browse all {worksLabel(collection.workCount)}
              </ButtonLink>
            )}
            <a
              href={iiif.collection(collection.id)}
              className={cn(buttonVariants({ variant: 'outline' }))}
              rel="noreferrer"
            >
              <span aria-hidden="true" className="font-mono text-[11px] font-bold">
                IIIF
              </span>
              IIIF collection
            </a>
            <Button
              variant="outline"
              onClick={() => {
                void shareLink(
                  collection.title,
                  `${window.location.origin}${location.pathname}${location.search}`,
                );
              }}
            >
              <Share2Icon aria-hidden="true" />
              Share
            </Button>
          </div>
        </div>
        {images.length > 0 && (
          <div aria-hidden="true" className="hidden h-[320px] grid-cols-3 gap-3 lg:grid">
            {images.map((fileSetId, index) => (
              <IiifImage
                key={fileSetId}
                fileSetId={fileSetId}
                size={500}
                className={cn(
                  'h-full w-full rounded-lg object-cover shadow-md ring-1 ring-border',
                  index === 1 && 'translate-y-4',
                )}
              />
            ))}
          </div>
        )}
      </Container>
    </section>
  );
}
