import type { ReactNode } from 'react';
import { Link } from 'react-router';
import type { Snippet, WorkHit } from '../../api/client.js';
import { IiifImage } from '../../components/IiifImage.js';
import {
  hitImageId,
  hitLink,
  ImageMatchBadge,
  matchedByImageOnly,
} from '../../components/ImageMatch.js';
import { workTitle } from '../../components/WorkCard.js';
import { yearsLabel } from '../../lib/dates.js';
import { cn } from '@/lib/utils';

/** A snippet's text with the words the query matched in `<mark>`. */
export function SnippetText({ snippet }: { readonly snippet: Snippet }) {
  const parts: ReactNode[] = [];
  let at = 0;
  for (const { start, end } of snippet.highlights) {
    if (start < at || end <= start || end > snippet.text.length) continue;
    if (start > at) parts.push(snippet.text.slice(at, start));
    parts.push(
      <mark key={start} className="rounded-sm bg-warning/20 px-0.5 text-foreground">
        {snippet.text.slice(start, end)}
      </mark>,
    );
    at = end;
  }
  if (at < snippet.text.length) parts.push(snippet.text.slice(at));
  return <>{parts}</>;
}

/**
 * A search hit as a list row: the image (the one that matched, for an image match), the serif
 * title, its creators, years · genre · collection, and the abstract around the match. Creators,
 * genres and the snippet come with the optional API additions (B1); without them a row shows
 * title, years and collection. A work found by its picture alone says so.
 */
export function WorkRow({
  work,
  className,
}: {
  readonly work: WorkHit;
  readonly className?: string;
}) {
  const facts = [
    yearsLabel(work.yearStart, work.yearEnd),
    work.genres?.[0],
    work.collections[0]?.title,
  ].filter((fact) => fact !== undefined);
  const creators = work.creators ?? [];
  return (
    <Link
      to={hitLink(work)}
      className={cn(
        'group flex gap-4 rounded-lg py-5 focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none sm:gap-5',
        className,
      )}
    >
      <div className="size-20 shrink-0 overflow-hidden rounded-lg bg-muted ring-1 ring-border sm:size-28">
        <IiifImage fileSetId={hitImageId(work)} size={300} className="size-full" />
      </div>
      <div className="min-w-0 flex-1">
        <p className="font-heading text-[17px] leading-snug font-semibold text-foreground decoration-border underline-offset-4 group-hover:underline">
          {workTitle(work)}
        </p>
        {creators.length > 0 && (
          <p className="mt-1 line-clamp-1 text-sm text-foreground/85">{creators.join('; ')}</p>
        )}
        {facts.length > 0 && (
          <p className="mt-1 text-[13px] text-muted-foreground">{facts.join(' · ')}</p>
        )}
        {work.snippet !== undefined && work.snippet !== null && (
          <p className="mt-2 line-clamp-2 text-sm text-muted-foreground">
            <SnippetText snippet={work.snippet} />
          </p>
        )}
        {matchedByImageOnly(work) && <ImageMatchBadge className="mt-2" />}
      </div>
      <span className="hidden shrink-0 self-start rounded-md bg-secondary px-2 py-0.5 font-mono text-[11px] text-muted-foreground xl:inline">
        {work.accessionNumber}
      </span>
    </Link>
  );
}
