import { CircleXIcon, RefreshCwIcon } from 'lucide-react';
import { ApiError } from '../api/client.js';
import { Alert, AlertAction, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';

/** A one-sentence explanation of a failed request for a visitor. */
export function describeError(error: unknown): string {
  if (error instanceof ApiError) {
    switch (error.status) {
      case 400:
        return 'The library could not understand this request. Check the address or start a new search.';
      case 404:
        return 'It is not in the library, or it is no longer public.';
      case 429:
        return 'The library is busy right now. Wait a moment and try again.';
      case 503:
        return 'The library is waking up. Try again in a moment.';
      default:
        return 'The library could not answer just now. Try again in a moment.';
    }
  }
  if (error instanceof TypeError) {
    return 'The library could not be reached. Check your connection and try again.';
  }
  return 'Something went wrong. Try again in a moment.';
}

/** A failed request: what happened, with Try again when the caller can repeat it. */
export function ProblemAlert({
  error,
  title = 'This part of the page could not load',
  onRetry,
  className,
}: {
  readonly error: unknown;
  readonly title?: string;
  readonly onRetry?: () => void;
  readonly className?: string;
}) {
  return (
    <Alert variant="destructive" className={className}>
      <CircleXIcon aria-hidden="true" />
      <AlertTitle>{title}</AlertTitle>
      <AlertDescription>{describeError(error)}</AlertDescription>
      {onRetry !== undefined && (
        <AlertAction>
          <Button variant="outline" size="sm" onClick={onRetry}>
            <RefreshCwIcon aria-hidden="true" />
            Try again
          </Button>
        </AlertAction>
      )}
    </Alert>
  );
}
