import { LibraryIcon, SearchIcon } from 'lucide-react';
import { useState } from 'react';
import type { PublicCollection } from '../api/client.js';
import { useCollections } from '../api/queries.js';
import { EmptyState } from '../components/EmptyState.js';
import { Container, PageTitle } from '../components/layout.js';
import { QueryState } from '../components/QueryState.js';
import { useDocumentTitle } from '../lib/document.js';
import { Button } from '@/components/ui/button';
import {
  CollectionCard,
  CollectionGridSkeleton,
  worksLabel,
} from './collections/CollectionCard.js';
import { countWord } from './home/Hero.js';

const ASPECT = 'aspect-[4/3]';

/** Collections whose title or description has every word of `text`, case-insensitively. */
export function filterCollections(
  collections: readonly PublicCollection[],
  text: string,
): PublicCollection[] {
  const words = text.toLocaleLowerCase('en-US').split(/\s+/).filter(Boolean);
  return collections.filter((item) => {
    const haystack = `${item.title} ${item.description ?? ''}`.toLocaleLowerCase('en-US');
    return words.every((word) => haystack.includes(word));
  });
}

function summary(collections: readonly PublicCollection[]): string {
  const works = collections.reduce((sum, item) => sum + item.workCount, 0);
  const count = collections.length;
  const text = `${countWord(count)} ${count === 1 ? 'collection' : 'collections'}`;
  return `${text.charAt(0).toUpperCase()}${text.slice(1)} · ${worksLabel(works)}`;
}

/** Filters as you type (the list is all on the page; nothing is fetched). */
function FilterBox({
  value,
  onChange,
}: {
  readonly value: string;
  readonly onChange: (value: string) => void;
}) {
  return (
    <div
      role="search"
      aria-label="Collections"
      className="flex h-9 w-full items-center gap-2.5 rounded-lg border border-input bg-card px-3 text-sm shadow-xs transition-[color,box-shadow] focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/20 sm:w-72"
    >
      <SearchIcon aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
      <input
        type="search"
        value={value}
        onChange={(event) => {
          onChange(event.target.value);
        }}
        aria-label="Filter collections"
        placeholder="Filter collections"
        autoComplete="off"
        className="h-full min-w-0 flex-1 bg-transparent text-foreground outline-none"
      />
    </div>
  );
}

/** The collections index: every collection by title, with a filter over titles and descriptions. */
export function CollectionsPage() {
  useDocumentTitle('Collections');
  const collections = useCollections();
  const [filter, setFilter] = useState('');
  return (
    <Container className="py-8 md:py-10">
      <div className="flex flex-wrap items-end justify-between gap-6">
        <PageTitle
          description={collections.data !== undefined ? summary(collections.data) : undefined}
        >
          Collections
        </PageTitle>
        <FilterBox value={filter} onChange={setFilter} />
      </div>
      <div className="mt-8">
        <QueryState
          query={collections}
          loading={<CollectionGridSkeleton count={6} aspect={ASPECT} />}
        >
          {(items) => {
            const shown = filterCollections(items, filter).sort((a, b) =>
              a.title.localeCompare(b.title, 'en-US'),
            );
            if (items.length === 0) {
              return (
                <EmptyState
                  icon={LibraryIcon}
                  title="No collections yet"
                  description="Collections appear here once the library publishes them."
                />
              );
            }
            return (
              <>
                <p className="sr-only" aria-live="polite">
                  {filter === '' ? '' : `${String(shown.length)} of ${String(items.length)} shown`}
                </p>
                {shown.length === 0 ? (
                  <EmptyState
                    title={`No collections match “${filter}”`}
                    description="Try another word, or search every work instead."
                    action={
                      <Button
                        variant="outline"
                        onClick={() => {
                          setFilter('');
                        }}
                      >
                        Show all collections
                      </Button>
                    }
                  />
                ) : (
                  <ul className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
                    {shown.map((collection) => (
                      <li key={collection.id}>
                        <CollectionCard collection={collection} aspect={ASPECT} />
                      </li>
                    ))}
                  </ul>
                )}
              </>
            );
          }}
        </QueryState>
      </div>
    </Container>
  );
}
