/**
 * Language names for the ISO 639-2 codes in records and facets (`eng` → English). The browser's
 * `Intl.DisplayNames` knows the terminology codes; the 20 bibliographic codes that differ
 * (`fre`, `ger`, `chi`, ...) are mapped to them first.
 */

const BIBLIOGRAPHIC_TO_TERMINOLOGY: Readonly<Record<string, string>> = {
  alb: 'sqi',
  arm: 'hye',
  baq: 'eus',
  bur: 'mya',
  chi: 'zho',
  cze: 'ces',
  dut: 'nld',
  fre: 'fra',
  geo: 'kat',
  ger: 'deu',
  gre: 'ell',
  ice: 'isl',
  mac: 'mkd',
  mao: 'mri',
  may: 'msa',
  per: 'fas',
  rum: 'ron',
  slo: 'slk',
  tib: 'bod',
  wel: 'cym',
};

let names: Intl.DisplayNames | undefined;

/** The English name of a language code, or the code itself when the browser does not know it. */
export function languageName(code: string): string {
  const lower = code.trim().toLowerCase();
  try {
    names ??= new Intl.DisplayNames(['en'], { type: 'language', fallback: 'none' });
    return names.of(BIBLIOGRAPHIC_TO_TERMINOLOGY[lower] ?? lower) ?? code;
  } catch {
    return code;
  }
}
