import { useSyncExternalStore } from 'react';

/**
 * Light or dark mode: the `dark` class on <html> switches the brand tokens (`tokens.css`). The
 * choice is kept per browser; until the user picks one, the operating system's preference
 * applies.
 */

export type ColorMode = 'light' | 'dark';

const STORAGE_KEY = 'cdl.color-mode';
const DARK_QUERY = '(prefers-color-scheme: dark)';

const listeners = new Set<() => void>();

function stored(): ColorMode | undefined {
  try {
    const value = window.localStorage.getItem(STORAGE_KEY);
    return value === 'light' || value === 'dark' ? value : undefined;
  } catch {
    return undefined;
  }
}

export function currentColorMode(): ColorMode {
  return stored() ?? (window.matchMedia(DARK_QUERY).matches ? 'dark' : 'light');
}

/** Puts the current mode on the document; call once before the first render. */
export function applyColorMode(mode: ColorMode = currentColorMode()): void {
  document.documentElement.classList.toggle('dark', mode === 'dark');
}

/**
 * Switches without animating every colour (buttons and badges have transitions): the
 * `cdl-switching` class turns transitions off until two frames later. A class, not an injected
 * <style> as next-themes does, because the CSP allows none.
 */
function withoutTransitions(change: () => void): void {
  const root = document.documentElement;
  root.classList.add('cdl-switching');
  change();
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      root.classList.remove('cdl-switching');
    });
  });
}

export function setColorMode(mode: ColorMode): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, mode);
  } catch {
    // Storage may be unavailable (private mode); the choice then lasts for this page only.
  }
  withoutTransitions(() => {
    applyColorMode(mode);
  });
  for (const listener of listeners) listener();
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function useColorMode(): [ColorMode, (mode: ColorMode) => void] {
  const mode = useSyncExternalStore(subscribe, currentColorMode);
  return [mode, setColorMode];
}
