import { useCollections, useSearch } from '../api/queries.js';
import { useSite } from '../app/context.js';
import { Container, SectionHeading } from '../components/layout.js';
import { QueryState } from '../components/QueryState.js';
import { useDocumentTitle } from '../lib/document.js';
import { CollectionCard, CollectionGridSkeleton } from './collections/CollectionCard.js';
import { featuredCollections, hasB1 } from './collections/data.js';
import { Hero } from './home/Hero.js';
import { AboutCard, DecadeChart, PopularSubjects, RecentlyAdded } from './home/sections.js';

/**
 * The home page: the hero with the big search box; the featured collections (`site.json`'s
 * order, else the API's `featured` flag); browse by decade and popular subjects from the facets
 * of an empty search; "recently added" when the API has the B1 additions; the about card.
 */
export function HomePage() {
  useDocumentTitle(undefined);
  const site = useSite();
  const collections = useCollections();
  const browse = useSearch({ limit: 1, facetLimit: 8 });
  return (
    <>
      <Hero works={browse.data?.total} collections={collections.data?.length} />
      <Container className="grid gap-14 pt-12 md:pt-14">
        <section aria-labelledby="featured-title" className="grid gap-6">
          <SectionHeading
            id="featured-title"
            link={{ text: 'All collections', to: '/collections' }}
          >
            Featured collections
          </SectionHeading>
          <QueryState query={collections} loading={<CollectionGridSkeleton />}>
            {(items) => (
              <ul className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
                {featuredCollections(items, site.featuredCollections).map((collection) => (
                  <li key={collection.id}>
                    <CollectionCard collection={collection} />
                  </li>
                ))}
              </ul>
            )}
          </QueryState>
        </section>
        {/* The featured collections above show the waking-up and error states for the page. */}
        {browse.data !== undefined && (
          <div className="grid gap-12 lg:grid-cols-[1.1fr_1fr] lg:gap-10">
            {browse.data.facets.year.length > 0 && (
              <DecadeChart decades={browse.data.facets.year} />
            )}
            {browse.data.facets.subject.length + browse.data.facets.genre.length > 0 && (
              <PopularSubjects facets={browse.data.facets} />
            )}
          </div>
        )}
        <RecentlyAdded enabled={collections.data !== undefined && hasB1(collections.data)} />
        <AboutCard />
      </Container>
    </>
  );
}
