import { ChevronsUpDownIcon, LayoutGridIcon, ListIcon, type LucideIcon } from 'lucide-react';
import type { SearchSort } from '../../api/client.js';
import { LATER_SORTS, SORT_LABELS, SORTS, type ResultsView } from './state.js';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

/**
 * The sort menu: relevance (with keywords only) and title always; the date and "recently added"
 * sorts only when the API serves the optional additions (B1), which older APIs refuse. A native
 * `<select>` styled as the design's trigger: the phone's own picker, and no popup code in the
 * first-page bundle.
 */
export function SortSelect(props: {
  value: SearchSort;
  /** Keywords are set: relevance can rank them. */
  withQuery: boolean;
  /** The API serves the B1 sorts. */
  later: boolean;
  onChange: (sort: SearchSort) => void;
  className?: string;
}) {
  const sorts = SORTS.filter(
    (sort) => props.later || !LATER_SORTS.includes(sort) || sort === props.value,
  );
  return (
    <label
      className={cn(
        'relative inline-flex h-9 items-center rounded-md border border-input bg-card text-sm shadow-xs transition-[color,box-shadow] focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/50 dark:bg-input/30',
        props.className,
      )}
    >
      <span
        aria-hidden="true"
        className="pointer-events-none absolute left-3 text-muted-foreground"
      >
        Sort
      </span>
      <select
        aria-label="Sort"
        value={props.value}
        onChange={(event) => {
          props.onChange(event.target.value as SearchSort);
        }}
        className="h-full cursor-pointer appearance-none rounded-md bg-transparent pr-8 pl-[calc(--spacing(3)+4ch)] font-medium text-foreground outline-none [&>option]:bg-popover [&>option]:text-popover-foreground"
      >
        {sorts.map((sort) => {
          const needsQuery = sort === 'relevance' && !props.withQuery;
          return (
            <option key={sort} value={sort} disabled={needsQuery}>
              {needsQuery ? `${SORT_LABELS[sort]} (with a search)` : SORT_LABELS[sort]}
            </option>
          );
        })}
      </select>
      <ChevronsUpDownIcon
        aria-hidden="true"
        className="pointer-events-none absolute right-2.5 size-4 text-muted-foreground"
      />
    </label>
  );
}

/** Grid of cards or a list of rows, as two pressed/unpressed buttons. */
export function ViewToggle(props: { value: ResultsView; onChange: (view: ResultsView) => void }) {
  const option = (value: ResultsView, label: string, Icon: LucideIcon) => (
    <Button
      variant="ghost"
      size="icon-xs"
      aria-label={label}
      aria-pressed={props.value === value}
      onClick={() => {
        props.onChange(value);
      }}
      className={cn(
        'rounded-md text-muted-foreground',
        props.value === value && 'bg-card text-foreground shadow-xs hover:bg-card',
      )}
    >
      <Icon aria-hidden="true" className="size-4" />
    </Button>
  );
  return (
    <div
      role="group"
      aria-label="View"
      className="inline-flex gap-0.5 rounded-lg bg-secondary p-0.5 ring-1 ring-border"
    >
      {option('grid', 'Grid', LayoutGridIcon)}
      {option('list', 'List', ListIcon)}
    </div>
  );
}
