/**
 * Per-route options for the shell, set as a route's `handle` in `App.tsx`: the home page has its
 * own big search box, and the search page pages on without a footer.
 */
export interface RouteHandle {
  /** The search box in the header (default true). */
  readonly headerSearch?: boolean;
  /** The site footer (default true). */
  readonly footer?: boolean;
}

export const NAV = [
  { text: 'Search', to: '/search' },
  { text: 'Collections', to: '/collections' },
  { text: 'About', to: '/about' },
] as const;

function useRouteHandle(): RouteHandle {
  const matches = useMatches();
  const handle: RouteHandle = matches.at(-1)?.handle ?? {};
  return handle;
}

/** Goes to the search page with `q` (keeping nothing else: a new search starts unfiltered). */
export function useSearchNavigation(): (q: string) => void {
  const navigate = useNavigate();
  return (q) => {
    void navigate(q === '' ? '/search' : `/search?${new URLSearchParams({ q }).toString()}`);
  };
}

/**
 * On the search page: searches for `q` keeping the filters, sort and view (the visitor refines
 * the current search). `replace` while typing, so Back skips the in-between queries.
 */
export function useSearchRefinement(): (q: string, options?: { replace?: boolean }) => void {
  const [params, setParams] = useSearchParams();
  return (q, options = {}) => {
    const next = new URLSearchParams(params);
    if (q === '') {
      next.delete('q');
      // Relevance needs keywords.
      if (next.get('sort') === 'relevance') next.delete('sort');
    } else {
      next.set('q', q);
    }
    setParams(next, { replace: options.replace ?? false, preventScrollReset: true });
  };
}

function ColorModeToggle() {
  const [mode, setMode] = useColorMode();
  const dark = mode === 'dark';
  return (
    <Button
      variant="ghost"
      size="icon"
      aria-label="Dark mode"
      aria-pressed={dark}
      onClick={() => {
        setMode(dark ? 'light' : 'dark');
      }}
    >
      {dark ? <SunIcon aria-hidden="true" /> : <MoonIcon aria-hidden="true" />}
    </Button>
  );
}

function navClass({ isActive }: { isActive: boolean }) {
  return cn(
    'rounded-md px-3 py-1.5 focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none',
    isActive
      ? 'bg-secondary font-medium text-foreground'
      : 'text-muted-foreground hover:text-foreground',
  );
}

function SiteHeader({ search }: { readonly search: boolean }) {
  const brand = useBrand();
  const site = useSite();
  const [params] = useSearchParams();
  const { pathname } = useLocation();
  const onSearch = useSearchNavigation();
  const onRefine = useSearchRefinement();
  const refining = pathname === '/search';
  const onType = (text: string) => {
    onRefine(text, { replace: true });
  };
  const wide = useRef<HTMLInputElement>(null);
  const [searchOpen, setSearchOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const q = pathname === '/search' ? (params.get('q') ?? '') : '';

  // "/" focuses the search box, as on most search sites (not while typing in a field).
  useEffect(() => {
    if (!search) return;
    function onKey(event: KeyboardEvent) {
      if (event.key !== '/' || event.metaKey || event.ctrlKey || event.altKey) return;
      const target = event.target as HTMLElement | null;
      if (target?.closest('input, textarea, select, [contenteditable="true"]')) return;
      event.preventDefault();
      // The wide box is hidden below lg; there the box opens under the header, focused.
      if (wide.current !== null && wide.current.offsetParent !== null) wide.current.focus();
      else setSearchOpen(true);
    }
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  }, [search]);

  const box = (className: string, narrow: boolean) => (
    <SearchBox
      size="sm"
      landmark="Site"
      value={q}
      onSearch={(text) => {
        setSearchOpen(false);
        if (refining) onRefine(text);
        else onSearch(text);
      }}
      onType={refining ? onType : undefined}
      shortcut="/"
      autoFocus={narrow}
      {...(narrow ? {} : { inputRef: wide })}
      className={className}
    />
  );

  return (
    <header className="border-b border-border bg-card">
      <Container className="flex h-16 items-center gap-4 lg:gap-7">
        <Link
          to="/"
          className="flex min-w-0 items-center gap-3 rounded-lg focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
        >
          <BrandMark />
          <span className="min-w-0 leading-tight">
            <span className="block truncate font-heading text-[17px] font-semibold tracking-tight">
              {brand.name}
            </span>
            <span className="hidden truncate text-xs text-muted-foreground sm:block">
              {site.tagline}
            </span>
          </span>
        </Link>
        <nav aria-label="Main" className="hidden items-center gap-1 text-sm md:flex">
          {NAV.map((item) => (
            <NavLink key={item.to} to={item.to} className={navClass}>
              {item.text}
            </NavLink>
          ))}
        </nav>
        <div className="ml-auto flex items-center gap-1 sm:gap-2">
          {search && box('hidden w-[340px] lg:flex', false)}
          {search && (
            <Button
              variant="ghost"
              size="icon"
              className="lg:hidden"
              aria-label="Search"
              aria-expanded={searchOpen}
              aria-controls="header-search"
              onClick={() => {
                setSearchOpen((open) => !open);
              }}
            >
              <SearchIcon aria-hidden="true" />
            </Button>
          )}
          <ColorModeToggle />
          <Button
            variant="ghost"
            size="icon"
            className="md:hidden"
            aria-label="Menu"
            onClick={() => {
              setMenuOpen(true);
            }}
          >
            <MenuIcon aria-hidden="true" />
          </Button>
        </div>
      </Container>
      {search && searchOpen && (
        <div id="header-search" className="border-t border-border py-3 lg:hidden">
          <Container>{box('w-full', true)}</Container>
        </div>
      )}
      <Sheet open={menuOpen} onOpenChange={setMenuOpen}>
        <SheetContent side="right" className="w-72">
          <SheetHeader>
            <SheetTitle className="font-heading text-lg">{brand.name}</SheetTitle>
            <SheetDescription>{site.tagline}</SheetDescription>
          </SheetHeader>
          <nav aria-label="Main" className="grid gap-1 px-4 text-[15px]">
            <NavLink
              to="/"
              end
              className={navClass}
              onClick={() => {
                setMenuOpen(false);
              }}
            >
              Home
            </NavLink>
            {NAV.map((item) => (
              <NavLink
                key={item.to}
                to={item.to}
                className={navClass}
                onClick={() => {
                  setMenuOpen(false);
                }}
              >
                {item.text}
              </NavLink>
            ))}
          </nav>
        </SheetContent>
      </Sheet>
    </header>
  );
}

const FOOTER_COLUMNS = [
  'lg:grid-cols-1',
  'lg:grid-cols-[1.6fr_1fr]',
  'lg:grid-cols-[1.6fr_1fr_1fr]',
  'lg:grid-cols-[1.6fr_1fr_1fr_1fr]',
  'lg:grid-cols-[1.6fr_1fr_1fr_1fr_1fr]',
];

function SiteFooter() {
  const brand = useBrand();
  const { description, footer } = useSite();
  const link = 'text-foreground/85 hover:text-foreground hover:underline underline-offset-4';
  return (
    <footer className="mt-16 border-t border-border bg-secondary/60">
      <Container
        className={cn(
          'grid gap-10 py-10 sm:grid-cols-2',
          FOOTER_COLUMNS[footer.groups.length] ?? FOOTER_COLUMNS[4],
        )}
      >
        <div>
          <div className="flex items-center gap-3">
            <BrandMark className="size-8" />
            <span className="font-heading text-base font-semibold">{brand.name}</span>
          </div>
          <p className="mt-3 max-w-sm text-sm text-muted-foreground">{description}</p>
          {footer.note !== undefined && (
            <p className="mt-2 max-w-sm text-sm text-muted-foreground">{footer.note}</p>
          )}
        </div>
        {footer.groups.map((group) => (
          <nav key={group.heading} aria-label={group.heading}>
            <h2 className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">
              {group.heading}
            </h2>
            <ul className="mt-3 grid gap-2 text-sm">
              {group.links.map((item) => (
                <li key={`${item.label} ${item.href}`}>
                  <SiteAnchor link={item} className={link} />
                </li>
              ))}
            </ul>
          </nav>
        ))}
      </Container>
      <div className="border-t border-border">
        <Container className="flex flex-wrap items-center justify-between gap-3 py-4 text-xs text-muted-foreground">
          <span>
            © {new Date().getFullYear()} {brand.name}
          </span>
          {footer.legal.length > 0 && (
            <ul className="flex flex-wrap gap-5">
              {footer.legal.map((item) => (
                <li key={`${item.label} ${item.href}`}>
                  <SiteAnchor link={item} className="hover:text-foreground hover:underline" />
                </li>
              ))}
            </ul>
          )}
        </Container>
      </div>
    </footer>
  );
}

/**
 * Every page renders inside the shell: the skip link, the header (brand, main navigation, search,
 * light/dark), `<main>` and the footer. After a navigation to another page, focus moves to
 * `<main>` so keyboard and screen reader users start at the new content.
 */
export function Shell() {
  const handle = useRouteHandle();
  const { pathname } = useLocation();
  const main = useRef<HTMLElement>(null);
  const previous = useRef(pathname);
  useEffect(() => {
    if (previous.current === pathname) return;
    previous.current = pathname;
    main.current?.focus({ preventScroll: true });
  }, [pathname]);

  return (
    <div className="flex min-h-svh flex-col bg-background text-[15px] text-foreground">
      <a
        href="#main"
        className="sr-only z-50 rounded-md bg-primary px-4 py-2 font-medium text-primary-foreground focus:not-sr-only focus:fixed focus:top-3 focus:left-3"
      >
        Skip to content
      </a>
      <SiteHeader search={handle.headerSearch ?? true} />
      <main id="main" ref={main} tabIndex={-1} className="flex-1 outline-none">
        <Outlet />
      </main>
      {(handle.footer ?? true) && <SiteFooter />}
      <Toaster position="bottom-center" />
      <ScrollRestoration />
    </div>
  );
}
