import { SearchIcon, XIcon } from 'lucide-react';
import { useEffect, useEffectEvent, useState, type Ref, type SubmitEvent } from 'react';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

const SIZES = {
  sm: { box: 'h-9 px-3 text-sm', icon: 'size-4' },
  default: { box: 'h-10 px-3 text-sm', icon: 'size-4' },
  lg: { box: 'h-13 pr-1.5 pl-4 text-base', icon: 'size-5' },
} as const;

/** How long typing pauses before `onType` searches. */
const TYPING_PAUSE_MS = 350;

/**
 * The search field of the header, the home page's hero and the "not found" page: a `search`
 * landmark (named by `landmark` when a page has more than one) around a labelled search input.
 * Submitting calls `onSearch` with the trimmed text; `value` follows the URL's `q` when it
 * changes, and the text stays editable in between. With `onType` (the search page) it also
 * searches as the visitor types, a moment after they pause.
 */
export function SearchBox({
  value = '',
  onSearch,
  size = 'default',
  label = 'Search the collections',
  landmark,
  button = false,
  shortcut,
  autoFocus = false,
  inputRef,
  onType,
  className,
}: {
  readonly value?: string;
  readonly onSearch: (q: string) => void;
  /** Called with the trimmed text once typing pauses, when it differs from `value`. */
  readonly onType?: ((q: string) => void) | undefined;
  readonly size?: keyof typeof SIZES;
  /** The input's accessible name, also shown as its placeholder. */
  readonly label?: string;
  /** The landmark's name, e.g. "Site" for the header's box. */
  readonly landmark?: string;
  /** Shows a primary "Search" button inside the box (hero, not found). */
  readonly button?: boolean;
  /** A key hint shown while the box is empty (the header's `/`). */
  readonly shortcut?: string;
  readonly autoFocus?: boolean;
  readonly inputRef?: Ref<HTMLInputElement>;
  readonly className?: string;
}) {
  const [text, setText] = useState(value);
  const [shown, setShown] = useState(value);
  // The last text this box searched for: when the URL next changes to it, that is the URL
  // catching up, which must not overwrite newer typing. Any change of the URL settles it,
  // whether it caught up or went elsewhere (Back from a work page, a facet link), so the next
  // change always shows its query. Kept longer, it hid the query on Back: the box stayed empty
  // and its as-you-type search replaced /search?q=rat with /search (2026-10-29), for instance
  // after Enter submitted the query the URL already showed, which changes no URL.
  const [sent, setSent] = useState<string>();
  if (value !== shown) {
    setShown(value);
    if (value !== sent) setText(value);
    setSent(undefined);
  }
  const sizing = SIZES[size];

  const live = onType !== undefined;
  const typed = useEffectEvent((q: string) => {
    setSent(q);
    onType?.(q);
  });
  useEffect(() => {
    const q = text.trim();
    if (!live || q === value) return;
    const timer = setTimeout(() => {
      typed(q);
    }, TYPING_PAUSE_MS);
    return () => {
      clearTimeout(timer);
    };
  }, [text, value, live]);

  function submit(event: SubmitEvent<HTMLFormElement>) {
    event.preventDefault();
    const q = text.trim();
    setText(q);
    setSent(q);
    onSearch(q);
  }

  return (
    <form
      role="search"
      aria-label={landmark}
      onSubmit={submit}
      className={cn(
        'flex items-center gap-2.5 rounded-lg border border-input bg-card shadow-xs transition-[color,box-shadow] focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/20',
        sizing.box,
        className,
      )}
    >
      <SearchIcon
        aria-hidden="true"
        className={cn('shrink-0 text-muted-foreground', sizing.icon)}
      />
      <input
        ref={inputRef}
        type="search"
        name="q"
        value={text}
        onChange={(event) => {
          setText(event.target.value);
        }}
        aria-label={label}
        placeholder={label}
        autoComplete="off"
        enterKeyHint="search"
        autoFocus={autoFocus}
        className="h-full min-w-0 flex-1 bg-transparent text-foreground outline-none [&::-webkit-search-cancel-button]:appearance-none"
      />
      {text !== '' && (
        <button
          type="button"
          aria-label="Clear search"
          onClick={() => {
            setText('');
          }}
          className="grid size-6 shrink-0 place-items-center rounded-sm text-muted-foreground hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
        >
          <XIcon aria-hidden="true" className="size-4" />
        </button>
      )}
      {text === '' && shortcut !== undefined && (
        <kbd
          aria-hidden="true"
          className="rounded border border-border bg-secondary px-1.5 font-mono text-[11px] text-muted-foreground"
        >
          {shortcut}
        </kbd>
      )}
      {button && (
        <Button type="submit" className="h-10 px-5">
          Search
        </Button>
      )}
    </form>
  );
}
