import { z } from 'zod';

/**
 * Per-deployment branding: the host may serve `/theme.json` next to `/config.json`; one build
 * serves every institution. The format is the staff UI's (copied from
 * `packages/admin-ui/src/theme/theme.ts` when this package was created), so one file brands both;
 * `signInImage` and `signInCaption` are accepted for that reason and unused here. Its colours
 * override the brand tokens of `src/styles/tokens.css` through `--brand-*` CSS variables set on
 * <html>, so no stylesheet is generated at run time (the CSP allows no inline styles). Without
 * a theme file, or with an invalid one, the default Cloud Digital Library look applies.
 *
 * ```json
 * {
 *   "name": "CU Boulder Digital Library",
 *   "shortName": "CU",
 *   "logo": "/brand/logo.svg",
 *   "radius": "0.375rem",
 *   "fonts": { "heading": "'Source Serif 4 Variable', serif" },
 *   "colors": {
 *     "light": { "primary": "#cfb87c", "primary-foreground": "#111111", "primary-text": "#6b5414" },
 *     "dark": { "primary": "#cfb87c", "primary-foreground": "#111111", "primary-text": "#e3d3a3" }
 *   }
 * }
 * ```
 */

/** Tokens a theme may set, as named in `tokens.css` (shadcn/ui names plus status colours). */
export const THEME_TOKENS = [
  'background',
  'foreground',
  'card',
  'card-foreground',
  'popover',
  'popover-foreground',
  'primary',
  'primary-foreground',
  'primary-text',
  'secondary',
  'secondary-foreground',
  'muted',
  'muted-foreground',
  'accent',
  'accent-foreground',
  'destructive',
  'destructive-foreground',
  'success',
  'warning',
  'info',
  'border',
  'input',
  'ring',
  'sidebar',
  'sidebar-foreground',
  'sidebar-primary',
  'sidebar-primary-foreground',
  'sidebar-accent',
  'sidebar-accent-foreground',
  'sidebar-border',
  'sidebar-ring',
] as const;
export type ThemeToken = (typeof THEME_TOKENS)[number];

/** A CSS colour: hex, or a colour function with plain numeric arguments (no `url()`, no `var()`). */
const Color = z
  .string()
  .regex(/^(#[0-9a-fA-F]{3,8}|(rgba?|hsla?|oklch|oklab|lch|lab)\([0-9.,%/\s+-]+\))$/, {
    message: 'must be a hex colour or rgb()/hsl()/oklch()/oklab()/lch()/lab()',
  });

const Palette = z.partialRecord(z.enum(THEME_TOKENS), Color);

/** A font-family list of the fonts the deployment serves itself (CSP `font-src 'self'`). */
const FontFamily = z.string().regex(/^[A-Za-z0-9 ,'"-]{1,200}$/);

export const Theme = z
  .object({
    /** The library's name in the header, the footer and the document title. */
    name: z.string().min(1).max(80).optional(),
    /** Two to four letters for the brand mark when there is no logo. */
    shortName: z.string().min(1).max(4).optional(),
    /** Same-origin path of a square logo image. */
    logo: z
      .string()
      .regex(/^\/[A-Za-z0-9/._-]+$/)
      .optional(),
    /** The staff UI's sign-in image and caption (same-origin path); unused by the public site. */
    signInImage: z
      .string()
      .regex(/^\/[A-Za-z0-9/._-]+$/)
      .optional(),
    signInCaption: z.string().max(200).optional(),
    radius: z
      .string()
      .regex(/^\d+(\.\d+)?(rem|px)$/)
      .optional(),
    fonts: z
      .object({ sans: FontFamily, heading: FontFamily, mono: FontFamily })
      .partial()
      .optional(),
    colors: z.object({ light: Palette, dark: Palette }).partial().optional(),
  })
  .strict();
export type Theme = z.infer<typeof Theme>;

export interface Brand {
  readonly name: string;
  readonly shortName: string;
  readonly logo: string | undefined;
}

export const DEFAULT_BRAND: Brand = {
  name: 'Cloud Digital Library',
  shortName: 'CDL',
  logo: undefined,
};

/** `Cloud Digital Library` → `CDL`: the first letters of up to three capitalised words. */
function initials(name: string): string {
  const letters = name.match(/\b\p{Lu}/gu) ?? [name.charAt(0).toUpperCase()];
  return letters.slice(0, 3).join('');
}

export function brandOf(theme: Theme | undefined): Brand {
  const name = theme?.name ?? DEFAULT_BRAND.name;
  return {
    name,
    shortName: theme?.shortName ?? initials(name),
    logo: theme?.logo,
  };
}

/** The `--brand-*` custom properties a theme sets on <html>. */
export function themeVariables(theme: Theme): Record<string, string> {
  const variables: Record<string, string> = {};
  for (const [mode, suffix] of [
    ['light', ''],
    ['dark', '-dark'],
  ] as const) {
    for (const [token, value] of Object.entries(theme.colors?.[mode] ?? {})) {
      variables[`--brand-${token}${suffix}`] = value;
    }
  }
  if (theme.radius !== undefined) variables['--brand-radius'] = theme.radius;
  for (const [role, family] of Object.entries(theme.fonts ?? {})) {
    if (family !== undefined) variables[`--brand-font-${role}`] = family;
  }
  return variables;
}

/** Sets the theme's variables on `root` (CSSOM, which the CSP allows). */
export function applyTheme(theme: Theme, root: HTMLElement = document.documentElement): void {
  for (const [name, value] of Object.entries(themeVariables(theme))) {
    root.style.setProperty(name, value);
  }
}

/**
 * `/theme.json`, or undefined when the deployment has none (any non-JSON or failed response,
 * e.g. CloudFront's 403 for a missing object) or it does not validate (logged, then ignored:
 * a broken theme must not take the site down).
 */
export async function loadTheme(fetchImpl: typeof fetch = fetch): Promise<Theme | undefined> {
  let value: unknown;
  try {
    const response = await fetchImpl(new URL('theme.json', document.baseURI).href, { cache: 'no-store' });
    if (!response.ok || !(response.headers.get('content-type') ?? '').includes('json')) {
      return undefined;
    }
    value = await response.json();
  } catch {
    return undefined;
  }
  const parsed = Theme.safeParse(value);
  if (!parsed.success) {
    console.warn(`theme.json ignored: ${z.prettifyError(parsed.error)}`);
    return undefined;
  }
  return parsed.data;
}
