import { Link } from 'react-router';
import { buttonVariants } from '@/components/ui/button';

/**
 * A page that failed to render (a bug, or a chunk that no longer exists after a deploy). The
 * shell is gone with it, so this stands alone and offers a reload.
 */
export function RouteError() {
  return (
    <main className="mx-auto grid min-h-svh max-w-xl content-center gap-4 p-8">
      <h1 className="font-heading text-3xl font-semibold tracking-tight">
        Something went wrong on this page
      </h1>
      <p className="text-muted-foreground">
        Reload the page to try again. If it keeps happening, start again from the home page.
      </p>
      <div className="flex gap-3">
        <button
          type="button"
          className={buttonVariants()}
          onClick={() => {
            window.location.reload();
          }}
        >
          Reload
        </button>
        <Link to="/" reloadDocument className={buttonVariants({ variant: 'outline' })}>
          Home
        </Link>
      </div>
    </main>
  );
}
