import { SearchIcon, type LucideIcon } from 'lucide-react';
import type { ReactNode } from 'react';
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
} from '@/components/ui/empty';
import { cn } from '@/lib/utils';

/**
 * What a list or panel shows when it has nothing: an icon, a serif title, one or two sentences
 * on why and what to do, and optionally an action (a button or link).
 */
export function EmptyState({
  title,
  description,
  icon: Icon = SearchIcon,
  action,
  className,
}: {
  readonly title: ReactNode;
  readonly description?: ReactNode;
  readonly icon?: LucideIcon;
  readonly action?: ReactNode;
  readonly className?: string;
}) {
  return (
    <Empty className={cn('gap-3 px-6 py-12', className)}>
      <EmptyHeader>
        <EmptyMedia className="mb-0 grid size-11 place-items-center rounded-full bg-secondary text-muted-foreground">
          <Icon aria-hidden="true" className="size-5" />
        </EmptyMedia>
        <p className="font-heading text-lg font-semibold text-foreground">{title}</p>
        {description !== undefined && (
          <EmptyDescription className="max-w-sm">{description}</EmptyDescription>
        )}
      </EmptyHeader>
      {action !== undefined && <EmptyContent>{action}</EmptyContent>}
    </Empty>
  );
}
