import { Link } from 'react-router';
import { useWork } from '../../api/queries.js';
import { useBrand, useSite } from '../../app/context.js';
import { useSearchNavigation } from '../../app/Shell.js';
import { IiifImage } from '../../components/IiifImage.js';
import { Container } from '../../components/layout.js';
import { SearchBox } from '../../components/SearchBox.js';
import { searchHref } from '../../lib/browse-links.js';

const WORDS = ['no', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'];

/** `3` → `three`, `12` → `12`: small counts read better as words in a sentence. */
export function countWord(count: number): string {
  return WORDS[count] ?? count.toLocaleString('en-US');
}

/** "20 works from three collections, free to view, zoom, download and reuse." */
export function holdingsLine(works: number, collections: number): string {
  const what = `${works.toLocaleString('en-US')} ${works === 1 ? 'work' : 'works'}`;
  const from =
    collections > 0
      ? ` from ${countWord(collections)} ${collections === 1 ? 'collection' : 'collections'}`
      : '';
  return `${what}${from}, free to view, zoom, download and reuse.`;
}

function HeroImage({ workId }: { readonly workId: string }) {
  const work = useWork(workId);
  const fileSetId = work.data?.representativeFileSetId;
  if (fileSetId === null || fileSetId === undefined) return null;
  return (
    <IiifImage
      fileSetId={fileSetId}
      size={1600}
      className="absolute inset-0 -z-10 size-full object-cover"
    />
  );
}

/**
 * The home page's hero: the `site.json` hero image (a work's representative image) under a
 * shade, the page's `<h1>`, what the library holds, the big search box and suggestion chips.
 */
export function Hero({
  works,
  collections,
}: {
  /** Public works and collections, once known. */
  readonly works: number | undefined;
  readonly collections: number | undefined;
}) {
  const brand = useBrand();
  const site = useSite();
  const onSearch = useSearchNavigation();
  const hero = site.hero;
  return (
    <section
      aria-labelledby="home-title"
      className="relative isolate overflow-hidden bg-viewer text-viewer-foreground"
    >
      {hero !== undefined && <HeroImage workId={hero.workId} />}
      <div className="absolute inset-0 -z-10 bg-gradient-to-r from-viewer/80 via-viewer/55 to-viewer/15" />
      <Container>
        <div className="max-w-[620px] py-14 md:py-24">
          {hero?.eyebrow !== undefined && (
            <p className="text-sm font-medium tracking-wide text-viewer-foreground/85">
              {hero.eyebrow}
            </p>
          )}
          <h1
            id="home-title"
            className="mt-3 font-heading text-[34px] leading-[1.08] font-semibold tracking-tight md:text-[52px] md:leading-[1.05]"
          >
            {hero?.title ?? brand.name}
          </h1>
          <p className="mt-4 min-h-[1.5em] text-base text-viewer-foreground/90 md:text-[17px]">
            {works !== undefined ? holdingsLine(works, collections ?? 0) : site.description}
          </p>
          <SearchBox
            size="lg"
            button
            landmark="Collections"
            className="mt-7 border-viewer-foreground/20 text-foreground"
            onSearch={onSearch}
          />
          {site.searchSuggestions.length > 0 && (
            <nav
              aria-label="Suggested searches"
              className="mt-4 flex flex-wrap items-center gap-2 text-sm text-viewer-foreground/85"
            >
              <span aria-hidden="true">Try</span>
              {site.searchSuggestions.map((suggestion) => (
                <Link
                  key={suggestion}
                  to={searchHref({}, suggestion)}
                  className="rounded-full bg-viewer-foreground/15 px-3 py-1 text-viewer-foreground ring-1 ring-viewer-foreground/25 backdrop-blur-sm hover:bg-viewer-foreground/25 focus-visible:ring-3 focus-visible:ring-ring focus-visible:outline-none"
                >
                  {suggestion}
                </Link>
              ))}
            </nav>
          )}
        </div>
      </Container>
      {hero?.caption !== undefined && (
        <Link
          to={`/works/${hero.workId}`}
          className="absolute right-4 bottom-3 hidden max-w-xs text-right text-xs text-viewer-foreground/80 hover:underline sm:block md:right-6 md:bottom-4"
        >
          {hero.caption}
        </Link>
      )}
    </section>
  );
}
