import { lazy, Suspense, useEffect } from 'react';
import { useParams } from 'react-router';
import { isNotFound } from '../api/client.js';
import { useManifest, useWork } from '../api/queries.js';
import { Container } from '../components/layout.js';
import { NotFound } from '../components/NotFound.js';
import { QueryState } from '../components/QueryState.js';
import { workTitle } from '../components/WorkCard.js';
import { useDocumentTitle } from '../lib/document.js';
import { Skeleton } from '@/components/ui/skeleton';

/** The page's code (reader, actions, citations) loads while the record and manifest do. */
const loadDetail = () => import('./work/WorkDetail.js');
const WorkDetail = lazy(loadDetail);

function WorkSkeleton() {
  return (
    <div aria-hidden="true" className="grid gap-6">
      <Skeleton className="h-4 w-1/3" />
      <div className="h-[min(66vh,600px)] min-h-80 animate-pulse rounded-xl bg-viewer motion-reduce:animate-none" />
      <Skeleton className="h-8 w-1/2" />
      <Skeleton className="h-4 w-1/3" />
    </div>
  );
}

function WorkView({ id }: { readonly id: string }) {
  useEffect(() => {
    void loadDetail();
  }, []);
  const work = useWork(id);
  const manifest = useManifest(id);
  useDocumentTitle(work.data !== undefined ? workTitle(work.data) : undefined);
  if (work.data !== undefined && manifest.data !== undefined) {
    return (
      <Suspense
        fallback={
          <Container className="py-6">
            <WorkSkeleton />
          </Container>
        }
      >
        <WorkDetail work={work.data} manifest={manifest.data} />
      </Suspense>
    );
  }
  if (isNotFound(work.error) || isNotFound(manifest.error)) return <NotFound />;
  return (
    <Container className="py-6">
      {work.data === undefined ? (
        <QueryState query={work} loading={<WorkSkeleton />}>
          {() => null}
        </QueryState>
      ) : (
        <QueryState query={manifest} loading={<WorkSkeleton />}>
          {() => null}
        </QueryState>
      )}
    </Container>
  );
}

/**
 * A work at `/works/:id?page=n`: the reader (deep zoom; a book's spreads, page strip and
 * contents), the title and byline, the actions (download, share, cite, IIIF), the description
 * and labelled record with links to filtered searches, the rights, the collections it is part of
 * and more works from its collection.
 */
export function WorkPage() {
  const { id = '' } = useParams();
  // A new work starts fresh (no state carried over from the previous one).
  return <WorkView key={id} id={id} />;
}
