import { useQuery } from '@tanstack/react-query';
import { unwrap, type PublicCollection } from '../../api/client.js';
import { keys, useApi } from '../../api/queries.js';

/** A collection's page: its slug, which the site resolves from the collections list. */
export function collectionPath(collection: Pick<PublicCollection, 'slug'>): string {
  return `/collections/${encodeURIComponent(collection.slug)}`;
}

/**
 * The collection a `/collections/:slug` URL names: by slug, or by id for links made from one.
 * Resolved from the list, so it works with an API that looks collections up by id only.
 */
export function resolveCollection(
  collections: readonly PublicCollection[],
  slug: string,
): PublicCollection | undefined {
  const wanted = slug.toLowerCase();
  return collections.find((item) => item.slug === wanted || item.id === wanted);
}

/** The deployed API has the optional B1 additions when its collections carry thumbnails. */
export function hasB1(collections: readonly PublicCollection[]): boolean {
  return collections.some((item) => item.thumbnailFileSetIds !== undefined);
}

/**
 * The collections the home page features: `site.json`'s slugs in their order when it names
 * them, else the API's `featured` ones first, filled up with the rest to `count`.
 */
export function featuredCollections(
  collections: readonly PublicCollection[],
  slugs: readonly string[] | undefined,
  count = 3,
): PublicCollection[] {
  if (slugs !== undefined) {
    return slugs
      .map((slug) => resolveCollection(collections, slug))
      .filter((item) => item !== undefined);
  }
  return [...collections]
    .sort((a, b) => Number(b.featured) - Number(a.featured))
    .slice(0, Math.max(count, collections.filter((item) => item.featured).length));
}

/**
 * A collection card's image: the first of the API's thumbnails (B1), else the representative
 * work's image, one extra request per card (shared with the work page's cache).
 */
export function useCollectionImage(collection: PublicCollection): string | null | undefined {
  const api = useApi();
  const thumbnail = collection.thumbnailFileSetIds?.[0];
  const workId = collection.representativeWorkId;
  const work = useQuery({
    queryKey: keys.work(workId ?? ''),
    queryFn: async () =>
      unwrap(await api.GET('/works/{id}', { params: { path: { id: workId ?? '' } } })),
    enabled: collection.thumbnailFileSetIds === undefined && workId !== null,
  });
  if (collection.thumbnailFileSetIds !== undefined) return thumbnail ?? null;
  if (workId === null || work.isError) return null;
  return work.data?.representativeFileSetId;
}
