import { useSearchParams } from 'react-router';
import { Container } from '../components/layout.js';
import { useDocumentTitle } from '../lib/document.js';
import { SearchScreen } from './search/SearchScreen.js';

/**
 * Search and browse at `/search?q&f.*&sort&view`: the screen is `search/SearchScreen.tsx`, its
 * URL state `search/state.ts`.
 */
export function SearchPage() {
  const [params] = useSearchParams();
  const q = params.get('q')?.trim() ?? '';
  useDocumentTitle(q === '' ? 'Browse' : `${q} – Search`);
  return (
    <Container>
      <SearchScreen />
    </Container>
  );
}
