import { XIcon } from 'lucide-react';
import type { Facets } from '../../api/client.js';
import type { SearchFilters } from '../../api/queries.js';
import { FACET_GROUPS, facetLabel, fallbackLabel } from './FacetPanel.js';
import { selectedOf, toggled, type FacetKey } from './state.js';
import { cn } from '@/lib/utils';

export interface ActiveFilter {
  readonly facet: FacetKey;
  readonly title: string;
  readonly value: string;
  readonly label: string;
}

/** The filters that are on, in panel order, labelled from the counts (or a fallback). */
export function activeFilters(
  filters: SearchFilters,
  facets: Facets | undefined,
  names: ReadonlyMap<string, string>,
  hide: readonly FacetKey[] = [],
): ActiveFilter[] {
  const selected = selectedOf(filters);
  return FACET_GROUPS.filter(({ key }) => !hide.includes(key)).flatMap(({ key, title }) =>
    selected[key].map((value) => {
      const counted = facets?.[key].find((v) => v.value === value);
      return {
        facet: key,
        title,
        value,
        label: counted !== undefined ? facetLabel(key, counted) : fallbackLabel(key, value, names),
      };
    }),
  );
}

/**
 * The filters that are on, as removable chips ("Collection Colorado in Photochrom ×"), and
 * "Clear filters" when there are any. Nothing renders without filters.
 */
export function FilterChips(props: {
  active: readonly ActiveFilter[];
  filters: SearchFilters;
  onChange: (filters: SearchFilters) => void;
  /** Leave out the facet's name (the phone sheet, where space is short). */
  compact?: boolean;
  /** Leave out "Clear filters" (the sheet has its own "Clear all"). */
  clear?: boolean;
  className?: string;
}) {
  if (props.active.length === 0) return null;
  return (
    <div className={cn('flex flex-wrap items-center gap-2', props.className)}>
      <ul aria-label="Active filters" className="flex flex-wrap gap-2">
        {props.active.map((filter) => (
          <li key={`${filter.facet} ${filter.value}`}>
            <button
              type="button"
              aria-label={`Remove filter ${filter.title}: ${filter.label}`}
              onClick={() => {
                props.onChange(toggled(props.filters, filter.facet, filter.value, false));
              }}
              className="inline-flex max-w-full items-center gap-1.5 rounded-full border border-primary/40 bg-primary/10 px-3 py-1 text-[13px] text-primary-text hover:bg-primary/15 focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
            >
              {props.compact !== true && (
                <span className="text-muted-foreground">{filter.title}</span>
              )}
              <span className="truncate">{filter.label}</span>
              <XIcon aria-hidden="true" className="size-3.5 shrink-0 opacity-70" />
            </button>
          </li>
        ))}
      </ul>
      {props.clear !== false && (
        <button
          type="button"
          onClick={() => {
            props.onChange({});
          }}
          className="ml-1 rounded-sm text-[13px] font-medium text-primary-text hover:underline focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
        >
          Clear filters
        </button>
      )}
    </div>
  );
}
