import type { SearchSort, WorkHit } from '../../api/client.js';
import type { SearchFilters } from '../../api/queries.js';

/**
 * The search screen's state, all of it in the URL so a search can be bookmarked, shared and
 * walked back: `/search?q=colorado&f.collection=<id>&f.year=1890-1899&sort=title&view=list`.
 * The `f.*` names are the Public API's; unknown or invalid values are dropped on the way in.
 */

export type ResultsView = 'grid' | 'list';

export interface SearchState {
  /** Keywords in web search syntax; empty to browse. */
  readonly q: string;
  readonly filters: SearchFilters;
  /** The sort the visitor picked; unset for the API's default (relevance with `q`, else title). */
  readonly sort?: SearchSort | undefined;
  readonly view: ResultsView;
}

/** The term facets: several values in one are ANDed (the API's `f.*` arrays). */
export type TermFacet = 'collection' | 'subject' | 'name' | 'genre' | 'language';
export type FacetKey = TermFacet | 'year';

export const SORTS: readonly SearchSort[] = ['relevance', 'title', 'date', '-date', 'recent'];
/** The sorts of the optional API additions (B1); an API without them answers 400. */
export const LATER_SORTS: readonly SearchSort[] = ['date', '-date', 'recent'];

export const SORT_LABELS: Readonly<Record<SearchSort, string>> = {
  relevance: 'Relevance',
  title: 'Title A–Z',
  date: 'Date, oldest first',
  '-date': 'Date, newest first',
  recent: 'Recently added',
};

type Mutable<T> = { -readonly [K in keyof T]: T[K] };

const TERM_FACETS: readonly TermFacet[] = ['collection', 'subject', 'name', 'genre', 'language'];
/** The API's limits on `q` and on values per facet. */
const MAX_Q = 500;
const MAX_VALUES = 10;
const MAX_VALUE_LENGTH = 500;
/** A year or a range, as the API takes it; negative years are BCE (`-3650--3641`). */
const YEAR = /^(-?\d{1,4})(?:-(-?\d{1,4}))?$/;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function valuesOf(params: URLSearchParams, facet: TermFacet): string[] | undefined {
  const values = [...new Set(params.getAll(`f.${facet}`).map((value) => value.trim()))]
    .filter((value) => value !== '' && value.length <= MAX_VALUE_LENGTH)
    .filter((value) => facet !== 'collection' || UUID.test(value))
    .slice(0, MAX_VALUES);
  return values.length > 0 ? values : undefined;
}

/** The search state in a URL's query; anything the API would refuse is left out. */
export function parseSearch(params: URLSearchParams): SearchState {
  const filters: Mutable<SearchFilters> = {};
  for (const facet of TERM_FACETS) {
    const values = valuesOf(params, facet);
    if (values !== undefined) filters[facet] = values;
  }
  const year = params.get('f.year')?.trim();
  if (year !== undefined && YEAR.test(year)) filters.year = year;
  const sort = params.get('sort') as SearchSort | null;
  return {
    q: (params.get('q') ?? '').trim().slice(0, MAX_Q),
    filters,
    ...(sort !== null && SORTS.includes(sort) ? { sort } : {}),
    view: params.get('view') === 'list' ? 'list' : 'grid',
  };
}

/**
 * The URL query for `state`, in a fixed order, leaving out defaults: no `view=grid`, and no
 * `sort=relevance` without keywords (the API would sort by title anyway).
 */
export function searchParamsOf(state: SearchState): URLSearchParams {
  const params = new URLSearchParams();
  if (state.q !== '') params.set('q', state.q);
  for (const facet of TERM_FACETS) {
    for (const value of state.filters[facet] ?? []) params.append(`f.${facet}`, value);
  }
  if (state.filters.year !== undefined) params.set('f.year', state.filters.year);
  if (state.sort !== undefined && !(state.sort === 'relevance' && state.q === '')) {
    params.set('sort', state.sort);
  }
  if (state.view === 'list') params.set('view', 'list');
  return params;
}

/** `/search?…` for `state` (`/search` alone for the default browse). */
export function searchHref(state: SearchState): string {
  const query = searchParamsOf(state).toString();
  return query === '' ? '/search' : `/search?${query}`;
}

/** The selected values of each facet, as the API's `value` strings. */
export function selectedOf(filters: SearchFilters): Record<FacetKey, readonly string[]> {
  return {
    collection: filters.collection ?? [],
    subject: filters.subject ?? [],
    name: filters.name ?? [],
    genre: filters.genre ?? [],
    language: filters.language ?? [],
    year: filters.year !== undefined ? [filters.year] : [],
  };
}

/** How many filter values are on (for "Filters · 2"). */
export function filterCount(filters: SearchFilters): number {
  return Object.values(selectedOf(filters)).reduce((sum, values) => sum + values.length, 0);
}

/**
 * `filters` with `value` of `facet` on or off. Term facets collect values (ANDed, at most 10);
 * the decade takes one (checking another swaps it), as `f.year` is a single range.
 */
export function toggled(
  filters: SearchFilters,
  facet: FacetKey,
  value: string,
  on: boolean,
): SearchFilters {
  if (facet === 'year') return { ...filters, year: on ? value : undefined };
  const current = filters[facet] ?? [];
  const values = on
    ? [...current.filter((v) => v !== value), value].slice(-MAX_VALUES)
    : current.filter((v) => v !== value);
  return { ...filters, [facet]: values.length > 0 ? values : undefined };
}

/**
 * Whether the API serves the optional additions (B1): their hit fields arrive on every hit, so
 * any hit tells. Without hits the answer is unknown, and the screen offers the original sorts.
 */
export function servesLaterAdditions(items: readonly WorkHit[]): boolean {
  return items.some((hit) => hit.creators !== undefined);
}
