import { z } from 'zod';

/**
 * A deployment's content: `/site.json`, served next to `/config.json` and `/theme.json` (which
 * carries the name, logo and colours, in the staff UI's format). Every field is optional; the
 * defaults below apply without a file, and an invalid file is logged and ignored rather than
 * keep the site from starting.
 *
 * ```json
 * {
 *   "tagline": "Digital collections",
 *   "description": "Photographs, posters and books from our special collections, free to explore.",
 *   "hero": {
 *     "workId": "0199c5a4-7e1f-7c3a-9d2e-4b5f6a7b8c9d",
 *     "eyebrow": "Photographs · Posters · Rare books",
 *     "title": "Explore our digital collections",
 *     "caption": "Grand Canyon, about 1898"
 *   },
 *   "searchSuggestions": ["Yellowstone", "Oz", "posters"],
 *   "featuredCollections": ["colorado-photochroms", "wpa-national-park-posters"],
 *   "about": {
 *     "title": "About the library",
 *     "body": ["First paragraph.", "Second paragraph."],
 *     "sections": [{ "heading": "Using these images", "body": ["Each item shows its rights."] }],
 *     "fileSetId": "0199c5a4-7e1f-7c3a-9d2e-4b5f6a7b8c9d"
 *   },
 *   "contact": {
 *     "name": "Special Collections",
 *     "email": "library@example.org",
 *     "phone": "+1 303 555 0100",
 *     "address": ["1 Main St", "Boulder, CO"],
 *     "hours": "Mon–Fri, 10 am – 5 pm"
 *   },
 *   "notFound": { "fileSetId": "0199c5a4-7e1f-7c3a-9d2e-4b5f6a7b8c9d", "caption": "The house in the cyclone" },
 *   "footer": {
 *     "groups": [{ "heading": "Explore", "links": [{ "label": "Collections", "href": "/collections" }] }],
 *     "legal": [{ "label": "Privacy", "href": "https://example.org/privacy" }],
 *     "note": "Demo images courtesy of the Library of Congress."
 *   }
 * }
 * ```
 */

/** An in-site path (`/about`), an `https:` URL or a `mailto:` address; nothing else is linked. */
const Href = z.string().regex(/^(\/(?!\/)\S*|https:\/\/\S+|mailto:\S+)$/, {
  message: 'must be a site path (/…), an https:// URL or a mailto: address',
});

const SiteLink = z.object({ label: z.string().min(1).max(80), href: Href }).strict();
export type SiteLink = z.infer<typeof SiteLink>;

const Text = (max: number) => z.string().min(1).max(max);

export const SiteFile = z
  .object({
    /** Under the name in the header and on the home page. */
    tagline: Text(120).optional(),
    /** The footer's blurb and the pages' `<meta name="description">`. */
    description: Text(500).optional(),
    /** The home page's hero image: a public work's representative image. */
    hero: z
      .object({
        workId: z.uuid(),
        /** A line above the title ("Photographs · Posters · Rare books"). */
        eyebrow: Text(80).optional(),
        /** The home page's `<h1>` (default: the name). */
        title: Text(120).optional(),
        caption: Text(200).optional(),
      })
      .strict()
      .optional(),
    /** Example searches offered under the home page's search box. */
    searchSuggestions: z.array(Text(60)).max(8).optional(),
    /** Collection slugs in the order the home page features them (default: the API's `featured`). */
    featuredCollections: z.array(Text(120)).max(12).optional(),
    about: z
      .object({
        title: Text(120).optional(),
        /** The about page's lead paragraphs; the first is also the home page's about card. */
        body: z.array(Text(2000)).min(1).max(20),
        /** Further sections of the about page, each under its own heading. */
        sections: z
          .array(z.object({ heading: Text(80), body: z.array(Text(2000)).min(1).max(10) }).strict())
          .max(8)
          .optional(),
        /** An image for the about page and the home page's about card: a file set id. */
        fileSetId: z.uuid().optional(),
      })
      .strict()
      .optional(),
    contact: z
      .object({
        /** Who answers ("Special Collections & Archives"). */
        name: Text(120).optional(),
        email: z.email().optional(),
        phone: Text(40).optional(),
        address: z.array(Text(120)).max(6).optional(),
        hours: Text(200).optional(),
      })
      .strict()
      .optional(),
    /** An image beside the "not found" page's text: a file set id, with its caption. */
    notFound: z
      .object({ fileSetId: z.uuid(), caption: Text(200).optional() })
      .strict()
      .optional(),
    footer: z
      .object({
        groups: z
          .array(z.object({ heading: Text(60), links: z.array(SiteLink).max(8) }).strict())
          .max(4)
          .optional(),
        legal: z.array(SiteLink).max(6).optional(),
        note: Text(300).optional(),
      })
      .strict()
      .optional(),
  })
  .strict();
export type SiteFile = z.infer<typeof SiteFile>;

export interface FooterGroup {
  readonly heading: string;
  readonly links: readonly SiteLink[];
}

/** The site's content with the defaults filled in. */
export interface Site {
  readonly tagline: string;
  readonly description: string;
  readonly hero: SiteFile['hero'];
  readonly searchSuggestions: readonly string[];
  readonly featuredCollections: readonly string[] | undefined;
  readonly about: SiteFile['about'];
  readonly contact: SiteFile['contact'];
  readonly notFound: SiteFile['notFound'];
  readonly footer: {
    readonly groups: readonly FooterGroup[];
    readonly legal: readonly SiteLink[];
    readonly note: string | undefined;
  };
}

export const DEFAULT_FOOTER_GROUPS: readonly FooterGroup[] = [
  {
    heading: 'Explore',
    links: [
      { label: 'Search', href: '/search' },
      { label: 'Collections', href: '/collections' },
    ],
  },
  {
    heading: 'About',
    links: [
      { label: 'About the library', href: '/about' },
      { label: 'Contact us', href: '/about#contact' },
    ],
  },
];

export function siteOf(file: SiteFile | undefined): Site {
  return {
    tagline: file?.tagline ?? 'Digital collections',
    description:
      file?.description ??
      'Photographs, posters and books from our special collections, free to explore.',
    hero: file?.hero,
    searchSuggestions: file?.searchSuggestions ?? [],
    featuredCollections: file?.featuredCollections,
    about: file?.about,
    contact: file?.contact,
    notFound: file?.notFound,
    footer: {
      groups: file?.footer?.groups ?? DEFAULT_FOOTER_GROUPS,
      legal: file?.footer?.legal ?? [],
      note: file?.footer?.note,
    },
  };
}

export const DEFAULT_SITE: Site = siteOf(undefined);

/**
 * `/site.json`, or undefined when the deployment has none (a failed or non-JSON response, such as
 * a dev server's `index.html` fallback) or it does not validate (logged, then ignored).
 */
export async function loadSite(fetchImpl: typeof fetch = fetch): Promise<SiteFile | undefined> {
  let value: unknown;
  try {
    const response = await fetchImpl(new URL('site.json', document.baseURI).href, { cache: 'no-store' });
    if (!response.ok || !(response.headers.get('content-type') ?? '').includes('json')) {
      return undefined;
    }
    value = await response.json();
  } catch {
    return undefined;
  }
  const parsed = SiteFile.safeParse(value);
  if (!parsed.success) {
    console.warn(`site.json ignored: ${z.prettifyError(parsed.error)}`);
    return undefined;
  }
  return parsed.data;
}
