import { keepPreviousData, useInfiniteQuery } from '@tanstack/react-query';
import {
  LayoutGridIcon,
  ListIcon,
  LoaderCircleIcon,
  SlidersHorizontalIcon,
  XIcon,
} from 'lucide-react';
import { useId, useState } from 'react';
import { Link } from 'react-router';
import type {
  FacetValue,
  PublicCollection,
  SearchResults,
  SearchSort,
  WorkHit,
} from '../../api/client.js';
import { fetchSearch, useApi, type SearchParams } from '../../api/queries.js';
import { EmptyState } from '../../components/EmptyState.js';
import { IiifImage } from '../../components/IiifImage.js';
import { QueryState } from '../../components/QueryState.js';
import { SearchBox } from '../../components/SearchBox.js';
import { WorkCard, WorkGridSkeleton, workFacts, workTitle } from '../../components/WorkCard.js';
import { decadeLabel } from '../../lib/dates.js';
import { languageName } from '../../lib/languages.js';
import { Button } from '@/components/ui/button';
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet';
import { cn } from '@/lib/utils';
import { worksLabel } from './CollectionCard.js';
import {
  activeFilters,
  toggleFilter,
  useBrowseState,
  type BrowseFacet,
  type BrowseState,
} from './browse-state.js';

const PAGE_SIZE = 24;
const SHOWN_VALUES = 5;

const GROUPS: readonly { facet: BrowseFacet; title: string }[] = [
  { facet: 'subject', title: 'Subject' },
  { facet: 'name', title: 'Name' },
  { facet: 'genre', title: 'Genre' },
  { facet: 'year', title: 'Decade' },
  { facet: 'language', title: 'Language' },
];

const TITLES = Object.fromEntries(GROUPS.map((group) => [group.facet, group.title])) as Record<
  BrowseFacet,
  string
>;

/** A facet value as a visitor reads it: decades as `1890s`, languages by name. */
function valueLabel(facet: BrowseFacet, value: string, label?: string): string {
  if (facet === 'year') return decadeLabel(value);
  if (facet === 'language') return languageName(value);
  return label ?? value;
}

const SORT_LABELS: Record<SearchSort, string> = {
  relevance: 'Best match',
  title: 'Title A–Z',
  date: 'Oldest first',
  '-date': 'Newest first',
  recent: 'Recently added',
};

/** The sorts to offer: relevance only with words; the date sorts only on an API with B1. */
function sortsFor(q: string, b1: boolean): SearchSort[] {
  return [
    ...(q !== '' ? (['relevance'] as const) : []),
    'title',
    ...(b1 ? (['date', '-date', 'recent'] as const) : []),
  ];
}

/** Pages of `GET /search` for "Show more", cached apart from `useSearch`'s single pages. */
function useSearchPages(params: SearchParams) {
  const api = useApi();
  return useInfiniteQuery({
    queryKey: ['search', 'pages', params],
    queryFn: ({ pageParam }) => fetchSearch(api, { ...params, cursor: pageParam }),
    initialPageParam: undefined as string | undefined,
    getNextPageParam: (last: SearchResults) => last.nextCursor ?? undefined,
    placeholderData: keepPreviousData,
  });
}

function FacetGroup({
  facet,
  title,
  values,
  filters,
  onToggle,
}: {
  readonly facet: BrowseFacet;
  readonly title: string;
  readonly values: readonly FacetValue[];
  readonly filters: BrowseState['filters'];
  readonly onToggle: (facet: BrowseFacet, value: string) => void;
}) {
  const [expanded, setExpanded] = useState(false);
  const listId = useId();
  const selected = (value: string) =>
    facet === 'year' ? filters.year === value : (filters[facet]?.includes(value) ?? false);
  // Chosen values stay in view when the list is folded.
  const shown = expanded
    ? values
    : values.filter((value, index) => index < SHOWN_VALUES || selected(value.value));
  const hidden = values.length - shown.length;
  return (
    <fieldset className="min-w-0 border-b border-border py-4 first:pt-0 last:border-0">
      <legend className="float-left w-full text-[13px] font-semibold">{title}</legend>
      <ul id={listId} className="clear-both grid grid-cols-[minmax(0,1fr)] pt-2">
        {shown.map((value) => (
          <li key={value.value}>
            <label className="flex cursor-pointer items-center gap-2.5 py-1 text-sm">
              <input
                type="checkbox"
                checked={selected(value.value)}
                onChange={() => {
                  onToggle(facet, value.value);
                }}
                className="size-4 shrink-0 cursor-pointer rounded-[4px] accent-primary focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
              />
              <span
                className={cn('min-w-0 flex-1 truncate', selected(value.value) && 'font-medium')}
              >
                {valueLabel(facet, value.value, value.label)}
              </span>{' '}
              <span className="text-xs text-muted-foreground tabular-nums">{value.count}</span>
            </label>
          </li>
        ))}
      </ul>
      {(hidden > 0 || expanded) && values.length > SHOWN_VALUES && (
        <button
          type="button"
          aria-expanded={expanded}
          aria-controls={listId}
          onClick={() => {
            setExpanded((value) => !value);
          }}
          className="mt-1 rounded-sm text-[13px] font-medium text-primary-text hover:underline focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
        >
          {expanded ? 'Show fewer' : `Show ${String(hidden)} more`}
        </button>
      )}
    </fieldset>
  );
}

function FacetPanel({
  facets,
  filters,
  onToggle,
}: {
  readonly facets: SearchResults['facets'];
  readonly filters: BrowseState['filters'];
  readonly onToggle: (facet: BrowseFacet, value: string) => void;
}) {
  const groups = GROUPS.filter((group) => facets[group.facet].length > 0);
  if (groups.length === 0) return null;
  return (
    <div>
      {groups.map((group) => (
        <FacetGroup
          key={group.facet}
          facet={group.facet}
          title={group.title}
          values={facets[group.facet]}
          filters={filters}
          onToggle={onToggle}
        />
      ))}
    </div>
  );
}

function WorkRow({ work }: { readonly work: WorkHit }) {
  const facts = workFacts(work);
  return (
    <Link
      to={`/works/${work.id}`}
      className="group flex gap-4 rounded-lg py-3 focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
    >
      <span className="block size-20 shrink-0 overflow-hidden rounded-md bg-muted ring-1 ring-border sm:size-24">
        <IiifImage fileSetId={work.representativeFileSetId} size={200} className="size-full" />
      </span>
      <span className="min-w-0">
        <span className="block font-heading text-base leading-snug font-semibold decoration-border underline-offset-4 group-hover:underline">
          {workTitle(work)}
        </span>
        {work.creators !== undefined && work.creators.length > 0 && (
          <span className="mt-0.5 block truncate text-sm text-foreground/85">
            {work.creators.join('; ')}
          </span>
        )}
        {facts !== '' && (
          <span className="mt-0.5 block text-[13px] text-muted-foreground">{facts}</span>
        )}
      </span>
    </Link>
  );
}

function ViewToggle({
  view,
  onChange,
}: {
  readonly view: BrowseState['view'];
  readonly onChange: (view: BrowseState['view']) => void;
}) {
  const option = (value: BrowseState['view'], label: string, Icon: typeof ListIcon) => (
    <button
      type="button"
      aria-label={label}
      aria-pressed={view === value}
      onClick={() => {
        onChange(value);
      }}
      className={cn(
        'inline-flex items-center rounded-md px-2.5 py-1 focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none',
        view === value
          ? 'bg-card text-foreground shadow-xs'
          : 'text-muted-foreground hover:text-foreground',
      )}
    >
      <Icon aria-hidden="true" className="size-4" />
    </button>
  );
  return (
    <div className="inline-flex h-9 items-center rounded-lg bg-secondary p-0.5 ring-1 ring-border">
      {option('grid', 'Grid view', LayoutGridIcon)}
      {option('list', 'List view', ListIcon)}
    </div>
  );
}

/**
 * A collection's works: the search screen scoped to `f.collection`, with words, facet filters
 * (AND, as the API defines them), chips, sort, grid or list and "Show more"; the state lives in
 * the URL. Below `lg` the filters open in a sheet.
 */
export function CollectionBrowse({
  collection,
  b1,
}: {
  readonly collection: PublicCollection;
  /** The deployed API has the optional additions (the date sorts). */
  readonly b1: boolean;
}) {
  const [state, update] = useBrowseState();
  const [sheetOpen, setSheetOpen] = useState(false);
  const sortId = useId();
  const pages = useSearchPages({
    q: state.q,
    filters: { ...state.filters, collection: [collection.id] },
    sort: state.sort,
    limit: PAGE_SIZE,
    facetLimit: 20,
  });
  const first = pages.data?.pages[0];
  // Cards here need not name this collection: they show their genre or another collection.
  const inCollection = (work: WorkHit): WorkHit => ({
    ...work,
    collections: work.collections.filter((item) => item.id !== collection.id),
  });
  const active = activeFilters(state.filters);
  const sorts = sortsFor(state.q, b1);
  const sort =
    state.sort !== undefined && sorts.includes(state.sort)
      ? state.sort
      : state.q !== ''
        ? 'relevance'
        : 'title';

  const onToggle = (facet: BrowseFacet, value: string) => {
    update({ filters: toggleFilter(state.filters, facet, value) });
  };
  const clearAll = () => {
    update({ filters: {}, q: '' });
  };
  const panel =
    first !== undefined ? (
      <FacetPanel facets={first.facets} filters={state.filters} onToggle={onToggle} />
    ) : null;

  return (
    <div className="grid gap-8 py-8 lg:grid-cols-[240px_minmax(0,1fr)] lg:gap-10">
      <aside aria-label="Filters" className="hidden lg:block">
        {panel}
      </aside>
      <section aria-labelledby="works-title" className="min-w-0">
        <h2 id="works-title" className="sr-only">
          Works in this collection
        </h2>
        <div className="flex flex-wrap items-center justify-between gap-3">
          <SearchBox
            size="sm"
            landmark="This collection"
            label="Search within this collection"
            value={state.q}
            onSearch={(q) => {
              update({ q, sort: undefined });
            }}
            className="w-full sm:w-96"
          />
          <div className="flex flex-wrap items-center gap-2">
            <Button
              variant="outline"
              className="lg:hidden"
              onClick={() => {
                setSheetOpen(true);
              }}
            >
              <SlidersHorizontalIcon aria-hidden="true" />
              Filters
              {active.length > 0 && (
                <span className="rounded-full bg-primary px-1.5 text-[11px] text-primary-foreground tabular-nums">
                  {active.length}
                </span>
              )}
            </Button>
            <label
              htmlFor={sortId}
              className="inline-flex h-9 items-center gap-2 rounded-md border border-input bg-card pl-3 text-sm shadow-xs focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/50"
            >
              <span className="text-muted-foreground">Sort</span>
              <select
                id={sortId}
                value={sort}
                onChange={(event) => {
                  const value = event.target.value as SearchSort;
                  update({
                    sort: value === (state.q !== '' ? 'relevance' : 'title') ? undefined : value,
                  });
                }}
                className="h-full cursor-pointer rounded-md bg-transparent pr-2 font-medium text-foreground outline-none"
              >
                {sorts.map((value) => (
                  <option key={value} value={value}>
                    {SORT_LABELS[value]}
                  </option>
                ))}
              </select>
            </label>
            <ViewToggle
              view={state.view}
              onChange={(view) => {
                update({ view });
              }}
            />
          </div>
        </div>

        {active.length > 0 && (
          <ul aria-label="Active filters" className="mt-4 flex flex-wrap items-center gap-2">
            {active.map(({ facet, value }) => (
              <li key={`${facet} ${value}`}>
                <button
                  type="button"
                  onClick={() => {
                    onToggle(facet, value);
                  }}
                  className="inline-flex items-center gap-1.5 rounded-full border border-primary/40 bg-primary/10 px-3 py-1 text-[13px] text-primary-text hover:bg-primary/15 focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
                >
                  <span className="text-muted-foreground">{TITLES[facet]}:</span>{' '}
                  {valueLabel(facet, value)}
                  <XIcon aria-hidden="true" className="size-3.5 opacity-70" />{' '}
                  <span className="sr-only">(remove)</span>
                </button>
              </li>
            ))}
            <li>
              <button
                type="button"
                onClick={clearAll}
                className="rounded-sm px-1 text-[13px] font-medium text-primary-text hover:underline focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
              >
                Clear all
              </button>
            </li>
          </ul>
        )}

        <div className="mt-6">
          <QueryState query={pages} loading={<WorkGridSkeleton count={6} />}>
            {(data) => {
              const total = data.pages[0]?.total ?? 0;
              const works = data.pages.flatMap((page) => page.items);
              if (works.length === 0) {
                return (
                  <EmptyState
                    title="No works match"
                    description="Try fewer or different words, or remove a filter."
                    action={
                      <Button variant="outline" onClick={clearAll}>
                        Clear filters
                      </Button>
                    }
                  />
                );
              }
              return (
                <>
                  <p className="mb-5 text-sm text-muted-foreground" aria-live="polite">
                    {active.length === 0 && state.q === ''
                      ? worksLabel(total)
                      : `${worksLabel(total)} match`}
                  </p>
                  {state.view === 'grid' ? (
                    <ul className="grid grid-cols-2 gap-x-5 gap-y-7 sm:grid-cols-3 md:gap-x-6 md:gap-y-8">
                      {works.map((work) => (
                        <li key={work.id}>
                          <WorkCard work={inCollection(work)} aspect="aspect-[3/4]" />
                        </li>
                      ))}
                    </ul>
                  ) : (
                    <ul className="divide-y divide-border">
                      {works.map((work) => (
                        <li key={work.id}>
                          <WorkRow work={inCollection(work)} />
                        </li>
                      ))}
                    </ul>
                  )}
                  {pages.hasNextPage && (
                    <div className="mt-8 flex flex-col items-center gap-2">
                      <p className="text-[13px] text-muted-foreground">
                        Showing {works.length} of {total}
                      </p>
                      <Button
                        variant="outline"
                        disabled={pages.isFetchingNextPage}
                        onClick={() => {
                          void pages.fetchNextPage();
                        }}
                      >
                        {pages.isFetchingNextPage && (
                          <LoaderCircleIcon
                            aria-hidden="true"
                            className="animate-spin motion-reduce:animate-none"
                          />
                        )}
                        Show more
                      </Button>
                    </div>
                  )}
                </>
              );
            }}
          </QueryState>
        </div>
      </section>

      <Sheet open={sheetOpen} onOpenChange={setSheetOpen}>
        <SheetContent side="left" className="w-80 overflow-y-auto">
          <SheetHeader>
            <SheetTitle className="font-heading text-lg">Filters</SheetTitle>
            <SheetDescription>
              {first !== undefined ? worksLabel(first.total) : collection.title}
            </SheetDescription>
          </SheetHeader>
          <div className="px-4 pb-6">{panel}</div>
        </SheetContent>
      </Sheet>
    </div>
  );
}
