import type { SearchFilters } from '../api/queries.js';

/**
 * Links into the search page with filters, in its URL format (`/search?q&f.*&sort&view`, the
 * Public API's own parameter names): the home page's decades and subjects, a collection's
 * "Browse all".
 */
export function searchHref(filters: SearchFilters = {}, q?: string): string {
  const params = new URLSearchParams();
  if (q !== undefined && q !== '') params.set('q', q);
  for (const [facet, value] of Object.entries(filters)) {
    for (const item of typeof value === 'string' ? [value] : ((value ?? []) as string[])) {
      if (item !== '') params.append(`f.${facet}`, item);
    }
  }
  const query = params.toString();
  return query === '' ? '/search' : `/search?${query}`;
}
