import { CSPProvider } from '@base-ui/react/csp-provider';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import type { ReactNode } from 'react';
import { createBrowserRouter, RouterProvider, type RouteObject } from 'react-router';
import type { PublicClient } from '../api/client.js';
import { ApiContext, retryDelay, shouldRetry } from '../api/queries.js';
import { NotFound } from '../components/NotFound.js';
import { AboutPage } from '../pages/AboutPage.js';
import { CollectionPage } from '../pages/CollectionPage.js';
import { CollectionsPage } from '../pages/CollectionsPage.js';
import { HomePage } from '../pages/HomePage.js';
import { SearchPage } from '../pages/SearchPage.js';
import { WorkPage } from '../pages/WorkPage.js';
import { ServicesContext, type SiteServices } from './context.js';
import { RouteError } from './RouteError.js';
import { Shell, type RouteHandle } from './Shell.js';
import { TooltipProvider } from '@/components/ui/tooltip';

const handle = (value: RouteHandle) => value;

/**
 * The site's routes. Each page lives in its own module under `src/pages/` so the slices that
 * build them (P1 search, P2 work, P3 home, collections and about) touch only their own files.
 */
export const ROUTES: RouteObject[] = [
  {
    path: '/',
    element: <Shell />,
    errorElement: <RouteError />,
    children: [
      { index: true, element: <HomePage />, handle: handle({ headerSearch: false }) },
      { path: 'search', element: <SearchPage />, handle: handle({ footer: false }) },
      { path: 'works/:id', element: <WorkPage /> },
      { path: 'collections', element: <CollectionsPage /> },
      { path: 'collections/:slug', element: <CollectionPage /> },
      { path: 'about', element: <AboutPage /> },
      { path: '*', element: <NotFound /> },
    ],
  },
];

export function createQueryClient(): QueryClient {
  return new QueryClient({
    defaultOptions: {
      queries: {
        retry: shouldRetry,
        retryDelay,
        refetchOnWindowFocus: false,
        // The Public API caches answers for 60 s or more at the edge; so can the browser.
        staleTime: 60_000,
      },
    },
  });
}

/**
 * Providers around a router (the browser router in the app, a memory router in tests). Base UI
 * renders no inline <style> elements (`disableStyleElements`): the site's CSP allows none, and
 * `styles/base.css` carries the one rule they would add.
 */
export function Providers(props: {
  services: SiteServices;
  api: PublicClient;
  queryClient: QueryClient;
  children: ReactNode;
}) {
  return (
    <ServicesContext.Provider value={props.services}>
      <ApiContext.Provider value={props.api}>
        <QueryClientProvider client={props.queryClient}>
          <CSPProvider disableStyleElements>
            <TooltipProvider>{props.children}</TooltipProvider>
          </CSPProvider>
        </QueryClientProvider>
      </ApiContext.Provider>
    </ServicesContext.Provider>
  );
}

export function App(props: { services: SiteServices; api: PublicClient }) {
  const router = createBrowserRouter(ROUTES);
  return (
    <Providers services={props.services} api={props.api} queryClient={createQueryClient()}>
      <RouterProvider router={router} />
    </Providers>
  );
}
