import { useParams } from 'react-router';
import { useCollections } from '../api/queries.js';
import { Container } from '../components/layout.js';
import { NotFound } from '../components/NotFound.js';
import { QueryState } from '../components/QueryState.js';
import { useDocumentTitle } from '../lib/document.js';
import { Skeleton } from '@/components/ui/skeleton';
import { CollectionBrowse } from './collections/CollectionBrowse.js';
import { CollectionHeader } from './collections/CollectionHeader.js';
import { hasB1, resolveCollection } from './collections/data.js';

function HeaderSkeleton() {
  return (
    <div aria-hidden="true" className="border-b border-border bg-card">
      <Container className="grid gap-4 py-12">
        <Skeleton className="h-3 w-40" />
        <Skeleton className="h-10 w-2/3" />
        <Skeleton className="h-4 w-1/2" />
        <Skeleton className="h-4 w-1/3" />
      </Container>
    </div>
  );
}

/**
 * A collection at `/collections/:slug`: its header, then its works to search and filter. The
 * slug is resolved from the collections list (also an id, for links made from one), which works
 * with an API that looks collections up by id only; an unknown one is "not found".
 */
export function CollectionPage() {
  const { slug = '' } = useParams();
  const collections = useCollections();
  const collection =
    collections.data !== undefined ? resolveCollection(collections.data, slug) : undefined;
  useDocumentTitle(collection?.title);
  return (
    <QueryState query={collections} loading={<HeaderSkeleton />}>
      {(items) =>
        collection === undefined ? (
          <NotFound />
        ) : (
          <>
            <CollectionHeader collection={collection} />
            <Container>
              {/* A new collection starts with its own filters and pages. */}
              <CollectionBrowse key={collection.id} collection={collection} b1={hasB1(items)} />
            </Container>
          </>
        )
      }
    </QueryState>
  );
}
