import { useQueryClient, type UseQueryResult } from '@tanstack/react-query';
import { CoffeeIcon, LoaderCircleIcon } from 'lucide-react';
import { useEffect, useId, useState, type ReactNode } from 'react';
import { DEFAULT_RETRY_AFTER_SECONDS, isNotFound, isWaking } from '../api/client.js';
import { ProblemAlert } from './ProblemAlert.js';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { cn } from '@/lib/utils';

/**
 * "The library is waking up": the Public API answers 503 + Retry-After while its database
 * resumes from auto-pause (about 15 s). The query keeps retrying on its own (`shouldRetry`);
 * this says so, counts down to the next attempt and offers "Try now". Remount it per attempt
 * (`key`) to restart the countdown.
 */
export function WakingUp({
  seconds = DEFAULT_RETRY_AFTER_SECONDS,
  retrying = true,
  onRetry,
  className,
}: {
  /** Seconds until the next automatic attempt. */
  readonly seconds?: number | undefined;
  /** False once the automatic attempts have run out. */
  readonly retrying?: boolean;
  readonly onRetry: () => void;
  readonly className?: string;
}) {
  const titleId = useId();
  const [remaining, setRemaining] = useState(Math.ceil(seconds));
  useEffect(() => {
    if (!retrying) return;
    const timer = setInterval(() => {
      setRemaining((value) => Math.max(0, value - 1));
    }, 1000);
    return () => {
      clearInterval(timer);
    };
  }, [retrying]);

  return (
    <section
      aria-labelledby={titleId}
      className={cn(
        'flex items-start gap-4 rounded-xl border border-info/30 bg-info/5 p-5',
        className,
      )}
    >
      <span className="grid size-10 shrink-0 place-items-center rounded-full bg-info/10 text-info">
        <CoffeeIcon aria-hidden="true" className="size-5" />
      </span>
      <div className="min-w-0">
        <div role="status">
          <h2 id={titleId} className="font-heading text-lg font-semibold">
            The library is waking up
          </h2>
          <p className="mt-1 text-sm text-muted-foreground">
            {retrying
              ? 'Our catalog sleeps when nobody is using it, to save costs. It takes about 15 seconds to start; this page retries by itself.'
              : 'It is taking longer than usual to start. Try again in a moment.'}
          </p>
        </div>
        <div className="mt-3 flex flex-wrap items-center gap-3 text-[13px] text-muted-foreground">
          {retrying && (
            <span className="inline-flex items-center gap-1.5 tabular-nums">
              <LoaderCircleIcon
                aria-hidden="true"
                className="size-4 animate-spin text-info motion-reduce:animate-none"
              />
              {remaining > 0 ? `Retrying in ${String(remaining)} s` : 'Retrying…'}
            </span>
          )}
          <Button variant="outline" size="sm" onClick={onRetry}>
            Try now
          </Button>
        </div>
      </div>
    </section>
  );
}

/**
 * The states of one query in a page region: `children(data)` once there is data (also while it
 * refreshes); "waking up" while the database resumes; `notFound` for a 404 when given (else the
 * problem); a problem with "Try again" for other failures; `loading` (a skeleton by default)
 * before the first answer.
 */
export function QueryState<T>({
  query,
  children,
  loading,
  notFound,
}: {
  readonly query: UseQueryResult<T>;
  readonly children: (data: T) => ReactNode;
  readonly loading?: ReactNode;
  readonly notFound?: ReactNode;
}) {
  const queryClient = useQueryClient();
  if (query.data !== undefined) return children(query.data);
  const reason: unknown = query.error ?? query.failureReason;
  const retry = () => {
    void query.refetch();
  };
  if (isWaking(reason)) {
    // A query waiting to retry ignores refetch(); cancel the wait (the query that failed with
    // this very error), then fetch again.
    const tryNow = () => {
      void queryClient
        .cancelQueries({ predicate: (cached) => cached.state.fetchFailureReason === reason })
        .then(retry);
    };
    return (
      <WakingUp
        key={query.failureCount}
        seconds={reason.retryAfter}
        retrying={!query.isError}
        onRetry={tryNow}
      />
    );
  }
  if (query.isError) {
    if (notFound !== undefined && isNotFound(query.error)) return notFound;
    return <ProblemAlert error={query.error} onRetry={retry} />;
  }
  return (
    loading ?? (
      <div aria-hidden="true" className="grid gap-3">
        <Skeleton className="h-6 w-1/3" />
        <Skeleton className="h-4 w-2/3" />
        <Skeleton className="h-4 w-1/2" />
      </div>
    )
  );
}
