import { ChevronDownIcon, FilterIcon, LoaderCircleIcon } from 'lucide-react';
import { useEffect, useId, useRef, useState, type ReactNode } from 'react';
import { useSearchParams } from 'react-router';
import { ApiError, type SearchResults, type SearchSort } from '../../api/client.js';
import { fetchSearch, keys, useApi, type SearchParams } from '../../api/queries.js';
import { useSearchRefinement } from '../../app/Shell.js';
import { EmptyState } from '../../components/EmptyState.js';
import { MatchedPages } from '../../components/ImageMatch.js';
import { ButtonLink } from '../../components/links.js';
import { QueryState } from '../../components/QueryState.js';
import { SearchBox } from '../../components/SearchBox.js';
import { WorkCard, WorkGridSkeleton } from '../../components/WorkCard.js';
import { collectionNamesOf, FacetGroups } from './FacetPanel.js';
import { activeFilters, FilterChips } from './FilterChips.js';
import {
  filterCount,
  LATER_SORTS,
  parseSearch,
  searchParamsOf,
  servesLaterAdditions,
  SORT_LABELS,
  type FacetKey,
  type SearchState,
} from './state.js';
