/** Works per "page" of results (six rows of four cards). */
export const PAGE_SIZE = 24;
/** Values per facet the panel can list (it shows six until "Show more"). */
export const FACET_LIMIT = 30;

const plural = (count: number, one: string, many: string) =>
  `${count.toLocaleString('en-US')} ${count === 1 ? one : many}`;

/**
 * The search state as it stands, and a way to change it: a new history entry each time unless
 * `replace`, and the page keeps its scroll position.
 */
export function useSearchState(): [
  SearchState,
  (next: SearchState, options?: { replace?: boolean }) => void,
] {
  const [params, setParams] = useSearchParams();
  const state = parseSearch(params);
  return [
    state,
    (next, options = {}) => {
      setParams(searchParamsOf(next), {
        replace: options.replace ?? false,
        preventScrollReset: true,
      });
    },
  ];
}

/** Every page of results for `params`, fetched one "Show more" at a time. */
export function useSearchPages(params: SearchParams) {
  const api = useApi();
  return useInfiniteQuery({
    queryKey: [...keys.search(params), 'pages'],
    queryFn: ({ pageParam }) =>
      fetchSearch(
        api,
        // Later pages need no facet counts: the first page's cover every match.
        pageParam === undefined ? params : { ...params, cursor: pageParam, facetLimit: 1 },
      ),
    initialPageParam: undefined as string | undefined,
    getNextPageParam: (last: SearchResults) => last.nextCursor ?? undefined,
    placeholderData: keepPreviousData,
  });
}

function heading(state: SearchState, first: SearchResults | undefined): string {
  if (state.q === '') return 'All works';
  if (first === undefined) return `Results for “${state.q}”`;
  if (first.total === 0) return `No results for “${state.q}”`;
  return `${plural(first.total, 'result', 'results')} for “${state.q}”`;
}

function summary(state: SearchState, first: SearchResults, filtered: boolean): string {
  if (state.q !== '') {
    const images = first.contentSearch === 'on' ? ' · matched in records and images' : '';
    return `Sorted by ${SORT_LABELS[first.sort].toLowerCase()}${images} · facet counts cover every match`;
  }
  if (filtered) return `${plural(first.total, 'work matches', 'works match')} your filters`;
  return `${plural(first.total, 'work', 'works')} · browse everything, or narrow with the filters`;
}

/**
 * The search and browse screen: keywords, the Filters panel (a column from lg up, a bottom
 * sheet below it), removable filter chips, sort, grid or list, and "Show more". All of its
 * state is in the URL (`state.ts`). `scope` fixes filters the visitor cannot change, such as a
 * collection page's own collection; that page brings its own `<h1>`, so the count is an `<h2>`.
 */
export function SearchScreen({
  scope,
  className,
}: {
  readonly scope?: { readonly collection: string };
  readonly className?: string;
}) {
  const [state, setState] = useSearchState();
  const refine = useSearchRefinement();
  const hide: readonly FacetKey[] = scope !== undefined ? ['collection'] : [];
  const params: SearchParams = {
    q: state.q,
    filters:
      scope !== undefined
        ? { ...state.filters, collection: [scope.collection, ...(state.filters.collection ?? [])] }
        : state.filters,
    sort: state.sort,
    limit: PAGE_SIZE,
    facetLimit: FACET_LIMIT,
  };
  const results = useSearchPages(params);
  const pages = results.data?.pages;
  const first = results.isPlaceholderData ? undefined : pages?.[0];
  const items = pages?.flatMap((page) => page.items) ?? [];
  const names = collectionNamesOf(items);
  const facets = pages?.[0]?.facets;
  const active = activeFilters(state.filters, facets, names, hide);
  const count = filterCount(state.filters);
  const headingId = useId();
  const [sheetOpen, setSheetOpen] = useState(false);

  // An API without the optional additions refuses their sorts (400): fall back to the default.
  const refused =
    results.error instanceof ApiError &&
    results.error.status === 400 &&
    state.sort !== undefined &&
    LATER_SORTS.includes(state.sort);
  useEffect(() => {
    if (refused) setState({ ...state, sort: undefined }, { replace: true });
  });

  const setFilters = (filters: SearchState['filters']) => {
    setState({ ...state, filters });
  };
  const sort: SearchSort =
    state.sort ?? pages?.[0]?.sort ?? (state.q === '' ? 'title' : 'relevance');
  const later = servesLaterAdditions(items);
  const Heading = scope !== undefined ? 'h2' : 'h1';

  const facetGroups = (
    <FacetGroups
      facets={facets}
      filters={state.filters}
      onChange={setFilters}
      collectionNames={names}
      hide={hide}
    />
  );

  return (
    <div className={cn('grid gap-10 py-8 lg:grid-cols-[260px_minmax(0,1fr)]', className)}>
      <aside aria-label="Filters" className="hidden lg:block">
        <div className="flex items-center justify-between pb-4">
          <h2 className="font-heading text-lg font-semibold">Filters</h2>
          {count > 0 && (
            <button
              type="button"
              aria-label="Clear all filters"
              onClick={() => {
                setFilters({});
              }}
              className="rounded-sm text-[13px] font-medium text-primary-text hover:underline focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
            >
              Clear all
            </button>
          )}
        </div>
        {facetGroups}
      </aside>
      <section aria-labelledby={headingId} className="min-w-0">
        {scope === undefined && (
          <SearchBox
            size="sm"
            landmark="Results"
            value={state.q}
            onSearch={(text) => {
              refine(text);
            }}
            onType={(text) => {
              refine(text, { replace: true });
            }}
            className="mb-4 lg:hidden"
          />
        )}
        <div className="flex flex-wrap items-end justify-between gap-x-4 gap-y-3">
          <div className="min-w-0">
            <Heading
              id={headingId}
              className={cn(
                'font-heading leading-tight font-semibold tracking-tight',
                scope !== undefined ? 'text-[22px]' : 'text-2xl md:text-[28px]',
              )}
            >
              {scope !== undefined && first !== undefined
                ? plural(first.total, 'work', 'works')
                : heading(state, first)}
            </Heading>
            {first !== undefined && (
              <p role="status" className="mt-1 text-sm text-muted-foreground">
                {summary(state, first, count > 0)}
                {first.contentSearch === 'unavailable' && (
                  <span className="block text-[13px]">
                    Matching by image is unavailable right now: these results match the records
                    only.
                  </span>
                )}
              </p>
            )}
          </div>
          <div className="flex w-full items-center gap-2 sm:w-auto">
            <Button
              variant={count > 0 ? 'default' : 'outline'}
              size="sm"
              className="lg:hidden"
              aria-haspopup="dialog"
              onClick={() => {
                setSheetOpen(true);
              }}
            >
              <FilterIcon aria-hidden="true" />
              {count > 0 ? `Filters · ${String(count)}` : 'Filters'}
            </Button>
            <SortSelect
              value={sort}
              withQuery={state.q !== ''}
              later={later}
              onChange={(next) => {
                setState({ ...state, sort: next });
              }}
              className="h-8 text-[13px] sm:h-9 sm:text-sm"
            />
            <span className="ml-auto sm:ml-0">
              <ViewToggle
                value={state.view}
                onChange={(view) => {
                  setState({ ...state, view });
                }}
              />
            </span>
          </div>
        </div>
        <FilterChips
          active={active}
          filters={state.filters}
          onChange={setFilters}
          className="mt-4"
        />
        <div className="mt-6">
          <QueryState
            query={results}
            loading={state.view === 'grid' ? <WorkGridSkeleton /> : <WorkGridSkeleton count={4} />}
          >
            {(data) => (
              <Results
                pages={data.pages}
                view={state.view}
                busy={results.isPlaceholderData}
                more={results.hasNextPage}
                loadingMore={results.isFetchingNextPage}
                onMore={() => {
                  void results.fetchNextPage();
                }}
                empty={
                  count > 0 ? (
                    <EmptyState
                      title="Nothing matches all these filters"
                      description="Filters narrow together: remove one to see more works."
                      action={
                        <Button
                          variant="outline"
                          onClick={() => {
                            setFilters({});
                          }}
                        >
                          Clear filters
                        </Button>
                      }
                    />
                  ) : (
                    <EmptyState
                      title="Try a different search"
                      description="Check the spelling, use fewer words, or browse every work."
                      action={<ButtonLink to="/search">Browse all works</ButtonLink>}
                    />
                  )
                }
              />
            )}
          </QueryState>
        </div>
      </section>
      <Sheet open={sheetOpen} onOpenChange={setSheetOpen}>
        <SheetContent
          side="bottom"
          className="top-16 gap-0 rounded-t-2xl data-[side=bottom]:h-auto"
        >
          <SheetHeader className="border-b border-border px-4 py-3">
            <SheetTitle className="font-heading text-lg font-semibold">Filters</SheetTitle>
            <SheetDescription className="sr-only">
              Narrow the results; they update as you choose.
            </SheetDescription>
          </SheetHeader>
          <div className="min-h-0 flex-1 overflow-y-auto px-4 pt-3 pb-4">
            <FilterChips
              active={active}
              filters={state.filters}
              onChange={setFilters}
              compact
              clear={false}
              className="pb-3"
            />
            {facetGroups}
          </div>
          <SheetFooter className="flex-row gap-2 border-t border-border p-3">
            <Button
              variant="outline"
              className="flex-1"
              disabled={count === 0}
              onClick={() => {
                setFilters({});
              }}
            >
              Clear all
            </Button>
            <Button
              className="flex-[2]"
              onClick={() => {
                setSheetOpen(false);
              }}
            >
              {first !== undefined
                ? `Show ${plural(first.total, 'result', 'results')}`
                : 'Show results'}
            </Button>
          </SheetFooter>
        </SheetContent>
      </Sheet>
    </div>
  );
}

/** The result cards or rows, and "Show more" with how many are shown. */
function Results(props: {
  pages: readonly SearchResults[];
  view: SearchState['view'];
  busy: boolean;
  more: boolean;
  loadingMore: boolean;
  onMore: () => void;
  empty: ReactNode;
}) {
  const items = props.pages.flatMap((page) => page.items);
  const total = props.pages[0]?.total ?? 0;
  const list = useRef<HTMLUListElement>(null);
  // After "Show more", focus moves to the first new result.
  const focusFrom = useRef<number>(undefined);
  useEffect(() => {
    const from = focusFrom.current;
    if (from === undefined || items.length <= from) return;
    focusFrom.current = undefined;
    list.current?.querySelectorAll<HTMLElement>(':scope > li > a')[from]?.focus();
  }, [items.length]);

  if (items.length === 0) return <>{props.empty}</>;
  const next = Math.min(PAGE_SIZE, total - items.length);
  return (
    <div
      aria-busy={props.busy}
      className={cn('transition-opacity motion-reduce:transition-none', props.busy && 'opacity-60')}
    >
      {props.view === 'grid' ? (
        <ul
          ref={list}
          className="grid grid-cols-2 gap-x-3 gap-y-5 sm:grid-cols-3 sm:gap-x-5 sm:gap-y-7 xl:grid-cols-4"
        >
          {items.map((work) => (
            <li key={work.id}>
              <WorkCard work={work} />
              <MatchedPages work={work} />
            </li>
          ))}
        </ul>
      ) : (
        <ul ref={list} className="-mt-5 divide-y divide-border">
          {items.map((work) => (
            <li key={work.id}>
              <WorkRow work={work} />
              <MatchedPages work={work} className="-mt-3 pb-5 pl-24 sm:pl-33" />
            </li>
          ))}
        </ul>
      )}
      <div className="mt-10 grid justify-items-center gap-2">
        {props.more && next > 0 ? (
          <>
            <Button
              variant="outline"
              disabled={props.loadingMore}
              onClick={() => {
                focusFrom.current = items.length;
                props.onMore();
              }}
            >
              {props.loadingMore ? (
                <LoaderCircleIcon
                  aria-hidden="true"
                  className="animate-spin motion-reduce:animate-none"
                />
              ) : null}
              {props.loadingMore ? 'Loading…' : `Show ${String(next)} more`}
              {!props.loadingMore && <ChevronDownIcon aria-hidden="true" className="opacity-70" />}
            </Button>
            <p className="text-[13px] text-muted-foreground">
              Showing {items.length.toLocaleString('en-US')} of {total.toLocaleString('en-US')}
            </p>
          </>
        ) : (
          <p className="text-sm text-muted-foreground">
            {total === 1
              ? 'Showing the only result'
              : `Showing all ${total.toLocaleString('en-US')} results`}
          </p>
        )}
      </div>
    </div>
  );
}
