import { useSearchParams } from 'react-router';
import type { SearchSort } from '../../api/client.js';
import type { SearchFilters } from '../../api/queries.js';

/** The term facets a visitor can narrow a collection by (each repeatable, ANDed). */
export const TERM_FACETS = ['subject', 'name', 'genre', 'language'] as const;
export type TermFacet = (typeof TERM_FACETS)[number];
export type BrowseFacet = TermFacet | 'year';

export type BrowseView = 'grid' | 'list';

/** A collection's browse state, kept in its URL as the search page keeps its own. */
export interface BrowseState {
  readonly q: string;
  /** Without `collection`: the page fixes that one. */
  readonly filters: Omit<SearchFilters, 'collection'>;
  /** Unset: the API's default (relevance with words, title without). */
  readonly sort: SearchSort | undefined;
  readonly view: BrowseView;
}

const SORTS: readonly SearchSort[] = ['relevance', 'title', 'date', '-date', 'recent'];

export function browseStateOf(params: URLSearchParams): BrowseState {
  const filters: Record<string, readonly string[] | string> = {};
  for (const facet of TERM_FACETS) {
    const values = params.getAll(`f.${facet}`).filter(Boolean);
    if (values.length > 0) filters[facet] = [...new Set(values)];
  }
  const year = params.get('f.year');
  if (year !== null && year !== '') filters['year'] = year;
  const sort = params.get('sort');
  return {
    q: params.get('q')?.trim() ?? '',
    filters,
    sort: SORTS.find((value) => value === sort),
    view: params.get('view') === 'list' ? 'list' : 'grid',
  };
}

export function paramsOf(state: BrowseState): URLSearchParams {
  const params = new URLSearchParams();
  if (state.q !== '') params.set('q', state.q);
  for (const facet of TERM_FACETS) {
    for (const value of state.filters[facet] ?? []) params.append(`f.${facet}`, value);
  }
  if (state.filters.year !== undefined) params.set('f.year', state.filters.year);
  if (state.sort !== undefined) params.set('sort', state.sort);
  if (state.view === 'list') params.set('view', 'list');
  return params;
}

/** Turns one facet value on or off; a decade replaces the one chosen before. */
export function toggleFilter(
  filters: BrowseState['filters'],
  facet: BrowseFacet,
  value: string,
): BrowseState['filters'] {
  if (facet === 'year') return { ...filters, year: filters.year === value ? undefined : value };
  const current = filters[facet] ?? [];
  return {
    ...filters,
    [facet]: current.includes(value)
      ? current.filter((item) => item !== value)
      : [...current, value],
  };
}

export function activeFilters(
  filters: BrowseState['filters'],
): { facet: BrowseFacet; value: string }[] {
  return [
    ...TERM_FACETS.flatMap((facet) => (filters[facet] ?? []).map((value) => ({ facet, value }))),
    ...(filters.year !== undefined ? [{ facet: 'year' as const, value: filters.year }] : []),
  ];
}

/** The browse state in the URL, and a setter that pushes a history entry per change. */
export function useBrowseState(): readonly [BrowseState, (next: Partial<BrowseState>) => void] {
  const [params, setParams] = useSearchParams();
  const state = browseStateOf(params);
  const update = (next: Partial<BrowseState>) => {
    setParams(paramsOf({ ...state, ...next }), { preventScrollReset: true });
  };
  return [state, update] as const;
}
