import { ChevronDownIcon } from 'lucide-react';
import { useId, useState } from 'react';
import type { FacetValue, Facets, WorkHit } from '../../api/client.js';
import type { SearchFilters } from '../../api/queries.js';
import { decadeLabel } from '../../lib/dates.js';
import { languageName } from '../../lib/languages.js';
import { selectedOf, toggled, type FacetKey } from './state.js';
import { Checkbox } from '@/components/ui/checkbox';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';
import { Skeleton } from '@/components/ui/skeleton';
import { cn } from '@/lib/utils';

/**
 * The Filters panel of the search screen (a column from lg up, a sheet below): one group of
 * checkboxes per facet with the number of matching works each would leave. Values in one group
 * narrow together (AND, as the API defines them); the decade takes one value.
 */

export const FACET_GROUPS: readonly { readonly key: FacetKey; readonly title: string }[] = [
  { key: 'collection', title: 'Collection' },
  { key: 'year', title: 'Decade' },
  { key: 'subject', title: 'Subject' },
  { key: 'name', title: 'Name' },
  { key: 'genre', title: 'Genre' },
  { key: 'language', title: 'Language' },
];

/** Values a group shows before "Show more". */
const SHOWN = 6;

/** Collection titles by id from the hits, for a selected collection the counts do not list. */
export function collectionNamesOf(items: readonly WorkHit[]): ReadonlyMap<string, string> {
  return new Map(items.flatMap((hit) => hit.collections.map((c) => [c.id, c.title] as const)));
}

/** A facet value as a reader sees it: language codes by name (before B1 labels them). */
export function facetLabel(facet: FacetKey, value: FacetValue): string {
  if (facet === 'language' && value.label === value.value) return languageName(value.value);
  return value.label;
}

/** A label for a selected value the counts do not list (no matches, or past the top values). */
export function fallbackLabel(
  facet: FacetKey,
  value: string,
  names: ReadonlyMap<string, string>,
): string {
  if (facet === 'collection') return names.get(value) ?? 'Selected collection';
  if (facet === 'year') return decadeLabel(value);
  if (facet === 'language') return languageName(value);
  return value;
}

/** The values a group lists: any selected value the counts leave out, then the counted ones. */
export function valuesOf(
  facet: FacetKey,
  facets: Facets,
  selected: readonly string[],
  names: ReadonlyMap<string, string>,
): { value: string; label: string; count: number }[] {
  const counted = facets[facet].map((v) => ({ ...v, label: facetLabel(facet, v) }));
  const missing = selected
    .filter((value) => !counted.some((v) => v.value === value))
    .map((value) => ({ value, label: fallbackLabel(facet, value, names), count: 0 }));
  return [...missing, ...counted];
}

function FacetGroup(props: {
  facet: FacetKey;
  title: string;
  values: { value: string; label: string; count: number }[];
  selected: readonly string[];
  onToggle: (value: string, on: boolean) => void;
}) {
  const [open, setOpen] = useState(true);
  const [all, setAll] = useState(false);
  const groupId = useId();
  const hidden = props.values.length - SHOWN;
  // Selected values stay in view when the group is folded to its first few.
  const shown = all
    ? props.values
    : props.values.filter((value, index) => index < SHOWN || props.selected.includes(value.value));
  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      render={<section className="border-b border-border py-4 first:pt-0 last:border-0" />}
    >
      <h3 id={groupId} className="text-[13px] font-semibold">
        <CollapsibleTrigger className="flex w-full items-center justify-between gap-2 rounded-sm text-left focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none">
          {props.title}
          <ChevronDownIcon
            aria-hidden="true"
            className={cn(
              'size-4 text-muted-foreground transition-transform motion-reduce:transition-none',
              open && 'rotate-180',
            )}
          />
        </CollapsibleTrigger>
      </h3>
      <CollapsibleContent>
        <div role="group" aria-labelledby={groupId} className="mt-2 grid">
          {shown.map((value) => {
            const checked = props.selected.includes(value.value);
            const works = `${value.count.toLocaleString('en-US')} ${value.count === 1 ? 'work' : 'works'}`;
            return (
              <label
                key={value.value}
                className={cn(
                  'flex min-w-0 cursor-pointer items-center gap-2.5 rounded-md py-1 text-sm',
                  value.count === 0 && !checked && 'text-muted-foreground',
                )}
              >
                <Checkbox
                  aria-label={`${value.label} (${works})`}
                  checked={checked}
                  onCheckedChange={(on) => {
                    props.onToggle(value.value, on);
                  }}
                />
                <span
                  className={cn('min-w-0 flex-1 truncate', checked && 'font-medium')}
                  title={value.label}
                >
                  {value.label}
                </span>
                <span className="text-xs text-muted-foreground tabular-nums">
                  {value.count.toLocaleString('en-US')}
                </span>
              </label>
            );
          })}
        </div>
        {hidden > 0 && (
          <button
            type="button"
            aria-expanded={all}
            aria-label={
              all
                ? `Show fewer ${props.title.toLowerCase()} filters`
                : `Show ${String(hidden)} more ${props.title.toLowerCase()} filters`
            }
            onClick={() => {
              setAll((value) => !value);
            }}
            className="mt-1 rounded-sm text-[13px] font-medium text-primary-text hover:underline focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
          >
            {all ? 'Show fewer' : `Show ${String(hidden)} more`}
          </button>
        )}
      </CollapsibleContent>
    </Collapsible>
  );
}

/**
 * The facet groups for the current answer; `facets` undefined shows a skeleton. `hide` leaves
 * out groups a scoped screen fixes (a collection page hides Collection).
 */
export function FacetGroups(props: {
  facets: Facets | undefined;
  filters: SearchFilters;
  onChange: (filters: SearchFilters) => void;
  collectionNames: ReadonlyMap<string, string>;
  hide?: readonly FacetKey[];
}) {
  const selected = selectedOf(props.filters);
  const facets = props.facets;
  if (facets === undefined) {
    return (
      <div className="grid gap-3" aria-hidden="true">
        {[0, 1, 2, 3, 4].map((key) => (
          <Skeleton key={key} className="h-4 w-3/4" />
        ))}
      </div>
    );
  }
  const groups = FACET_GROUPS.filter(({ key }) => !(props.hide ?? []).includes(key))
    .map((group) => ({
      ...group,
      values: valuesOf(group.key, facets, selected[group.key], props.collectionNames),
    }))
    .filter((group) => group.values.length > 0);
  if (groups.length === 0) {
    return <p className="text-sm text-muted-foreground">No filters for these results.</p>;
  }
  return (
    <div>
      {groups.map((group) => (
        <FacetGroup
          key={group.key}
          facet={group.key}
          title={group.title}
          values={group.values}
          selected={selected[group.key]}
          onToggle={(value, on) => {
            props.onChange(toggled(props.filters, group.key, value, on));
          }}
        />
      ))}
    </div>
  );
}
