import './zod-config.js';
// Self-hosted fonts (the CSP allows fonts from the site's own origin only).
import '@fontsource-variable/inter';
import '@fontsource-variable/source-serif-4';
import '@fontsource-variable/jetbrains-mono';
import './styles/index.css';
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { createPublicClient } from './api/client.js';
import { App } from './app/App.js';
import { loadConfig } from './config/config.js';
import { loadSite, siteOf } from './config/site.js';
import { setMetaDescription } from './lib/document.js';
import { applyColorMode } from './theme/color-mode.js';
import { applyTheme, brandOf, loadTheme } from './theme/theme.js';

const container = document.getElementById('root');
if (container === null) throw new Error('index.html has no #root');
const root = createRoot(container);
applyColorMode();

try {
  const [config, siteFile, theme] = await Promise.all([loadConfig(), loadSite(), loadTheme()]);
  if (theme !== undefined) applyTheme(theme);
  const site = siteOf(siteFile);
  const brand = brandOf(theme);
  document.title = brand.name;
  setMetaDescription(site.description);
  root.render(
    <StrictMode>
      <App
        services={{ config, site, brand }}
        api={createPublicClient({ baseUrl: config.apiBaseUrl })}
      />
    </StrictMode>,
  );
} catch (error) {
  root.render(
    <main className="mx-auto max-w-xl p-8">
      <h1 className="font-heading text-2xl font-semibold">The library could not start</h1>
      <p className="mt-2 text-muted-foreground">
        {error instanceof Error ? error.message : String(error)}
      </p>
    </main>,
  );
}
