import { Link } from 'react-router';
import type { PublicCollection } from '../../api/client.js';
import { IiifImage } from '../../components/IiifImage.js';
import { cn } from '@/lib/utils';
import { collectionPath, useCollectionImage } from './data.js';

export function worksLabel(count: number): string {
  return `${count.toLocaleString('en-US')} ${count === 1 ? 'work' : 'works'}`;
}

/**
 * A collection in a grid (home page, collections index): its image, a "Featured" mark, the work
 * count, the serif title as an `<h3>` and the description, linking to the collection.
 */
export function CollectionCard({
  collection,
  aspect = 'aspect-[16/9]',
  className,
}: {
  readonly collection: PublicCollection;
  /** The image box: `aspect-[16/9]` on the home page, `aspect-[4/3]` on the index. */
  readonly aspect?: string;
  readonly className?: string;
}) {
  const image = useCollectionImage(collection);
  return (
    <Link
      to={collectionPath(collection)}
      className={cn(
        'group block h-full overflow-hidden rounded-xl border border-border bg-card shadow-xs focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none',
        className,
      )}
    >
      <div className={cn('overflow-hidden bg-muted', aspect)}>
        {image === undefined ? (
          <div className="size-full animate-pulse bg-muted motion-reduce:animate-none" />
        ) : (
          <IiifImage
            fileSetId={image}
            size={800}
            className="size-full transition group-hover:scale-[1.02] motion-reduce:transition-none motion-reduce:group-hover:scale-100"
          />
        )}
      </div>
      <div className="p-5">
        <p className="flex items-center gap-2 text-[13px] text-muted-foreground">
          {collection.featured && (
            <span className="rounded-full bg-primary/10 px-2 py-0.5 text-[11px] font-semibold tracking-wide text-primary-text uppercase">
              Featured
            </span>
          )}
          {worksLabel(collection.workCount)}
        </p>
        <h3 className="mt-1.5 font-heading text-xl leading-snug font-semibold decoration-border underline-offset-4 group-hover:underline">
          {collection.title}
        </h3>
        {collection.description !== null && (
          <p className="mt-2 line-clamp-3 text-sm text-muted-foreground">
            {collection.description}
          </p>
        )}
      </div>
    </Link>
  );
}

/** A grid of `CollectionCard`-sized placeholders while the list loads. */
export function CollectionGridSkeleton({
  count = 3,
  aspect = 'aspect-[16/9]',
}: {
  readonly count?: number;
  readonly aspect?: string;
}) {
  return (
    <div aria-hidden="true" className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
      {Array.from({ length: count }, (_, index) => (
        <div key={index} className="overflow-hidden rounded-xl border border-border bg-card">
          <div className={cn('animate-pulse bg-muted motion-reduce:animate-none', aspect)} />
          <div className="grid gap-2 p-5">
            <div className="h-3 w-1/4 rounded bg-muted" />
            <div className="h-5 w-3/4 rounded bg-muted" />
            <div className="h-3 w-full rounded bg-muted/70" />
          </div>
        </div>
      ))}
    </div>
  );
}
